const plainsNorthItineraries=[{"attractions":[{"description":"North Dakota's only national park protects the rugged badlands where a young Theodore Roosevelt ranched in the 1880s. The South Unit's scenic loop offers bison, prairie dogs, and painted canyon overlooks. Stop at the Maltese Cross Cabin and visitor center in Medora first.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Theodore%20Roosevelt%20National%20Park%20Medora%20ND","name":"Theodore Roosevelt National Park","officialUrl":"https://www.nps.gov/thro/","photos":["assets/plains-north/images/medora-nd-badlands/attr1-1.jpg","assets/plains-north/images/medora-nd-badlands/attr1-2.jpg","assets/plains-north/images/medora-nd-badlands/attr1-3.jpg","assets/plains-north/images/medora-nd-badlands/attr1-4.jpg"],"price":"$30/vehicle, 7-day pass (est.)"},{"description":"A patriotic outdoor musical revue performed nightly all summer in the Burning Hills Amphitheatre. Expect live bands, comedy, and tributes to Theodore Roosevelt with the badlands as the backdrop. The pre-show pitchfork steak fondue is a Medora tradition.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Medora%20Musical%20Medora%20ND","name":"Medora Musical","officialUrl":"https://medora.com/","photos":["assets/plains-north/images/medora-nd-badlands/attr2-1.jpg","assets/plains-north/images/medora-nd-badlands/attr2-2.jpg","assets/plains-north/images/medora-nd-badlands/attr2-3.jpg","assets/plains-north/images/medora-nd-badlands/attr2-4.jpg"],"price":"$52/adult, $26/child (est.)"},{"description":"The 26-room summer home of Antoine de Vallombrosa, the Marquis de Mores, who founded Medora in 1883. Guided tours share tales of frontier ambition, duels, and cattle ranching. The site sits on a bluff overlooking the town.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Chateau%20de%20Mores%20Medora%20ND","name":"Chateau de Mores State Historic Site","officialUrl":"https://www.history.nd.gov/historicsites/chateau/","photos":["assets/plains-north/images/medora-nd-badlands/attr3-1.jpg","assets/plains-north/images/medora-nd-badlands/attr3-2.jpg","assets/plains-north/images/medora-nd-badlands/attr3-3.jpg","assets/plains-north/images/medora-nd-badlands/attr3-4.jpg"],"price":"$10/adult, $5/child 6–15 (est.)"},{"description":"Perched on the rim of the badlands just off I-94, this visitor center frames one of the most colorful canyon views in the park. Exhibits explain the geology, and a short trail dips below the rim. An easy, rewarding stop on the way in or out of Medora.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Painted%20Canyon%20Visitor%20Center%20Medora%20ND","name":"Painted Canyon Visitor Center","officialUrl":"https://www.nps.gov/thro/","photos":["assets/plains-north/images/medora-nd-badlands/attr4-1.jpg","assets/plains-north/images/medora-nd-badlands/attr4-2.jpg","assets/plains-north/images/medora-nd-badlands/attr4-3.jpg","assets/plains-north/images/medora-nd-badlands/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"May–September","budget":950,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, show tickets, meals, and gas; lodging not included.","days":3,"destination":"Medora, ND","driveNotes":"Medora sits right off I-94 in western North Dakota, about 2 hours from Bismarck and 4.5 from Fargo. The park's South Unit loop is paved and easy; fill up gas in Medora since stations are sparse west of town. Summer thunderstorms roll through fast — check the sky before long hikes.","familyFriendly":"Best for ages 5+. Trails are short and scenic; the Musical runs late, so plan a restful afternoon first.","heroPhoto":"assets/plains-north/images/medora-nd-badlands/hero.jpg","highlights":["Spot wild bison and prairie dogs on the South Unit scenic loop","Sing along at the Medora Musical in an open-air amphitheatre","Walk through Theodore Roosevelt's Maltese Cross Cabin","Watch the sunset over Painted Canyon's striped buttes","Step into an 1880s frontier town at the Chateau de Mores"],"id":"medora-nd-badlands","interests":["family","outdoors","nature","scenic","historical-sites"],"itinerary":[{"afternoon":{"cost":"Included with park pass (est.)","description":"Tour the tiny cabin where Theodore Roosevelt lived as a young rancher, then watch the park film and explore the exhibits inside the visitor center. Rangers often have junior ranger booklets for kids to earn a badge.","stop":"Maltese Cross Cabin & Visitor Center","time":"1:30 PM – 3:30 PM"},"day":1,"evening":{"cost":"$15–$25 for treats (est.)","description":"Wander the boardwalks of old-time Medora, pop into the souvenir shops, and grab ice cream before an early night. The town is small and very walkable for little legs.","stop":"Downtown Medora stroll & ice cream","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"$30 per vehicle, 7-day pass (est.)","description":"Drive the 36-mile loop through the heart of the badlands, stopping at pullouts for striped canyons and prairie dog towns. Kids love spotting bison and wild horses from the car windows. Allow plenty of stops — the views change around every bend.","stop":"Theodore Roosevelt National Park — South Unit Scenic Loop","time":"9:00 AM – 12:30 PM"},"title":"Badlands & Bison"},{"afternoon":{"cost":"$12/adult, kids $6 (est.)","description":"Saddles, rodeo gear, and Native American artifacts tell the story of ranching culture in the northern plains. Interactive touches keep younger visitors engaged through the galleries.","stop":"North Dakota Cowboy Hall of Fame","time":"1:00 PM – 3:00 PM"},"day":2,"evening":{"cost":"$52/adult, kids $26 (est.)","description":"This long-running outdoor variety show celebrates Roosevelt and the Old West with music, comedy, and a burning-hills backdrop. Arrive early for the pre-show and a famous pitchfork steak fondue dinner if you like.","stop":"Medora Musical","time":"7:30 PM – 10:00 PM"},"morning":{"cost":"$10/adult, kids 6–15 $5 (est.)","description":"Tour the 1883 hunting lodge of the Marquis de Mores, the French aristocrat who founded Medora. The guided tour brings frontier stories to life, and the grounds have room for kids to roam.","stop":"Chateau de Mores State Historic Site","time":"9:00 AM – 11:30 AM"},"title":"Frontier History"},{"afternoon":{"cost":"Free (est.)","description":"Learn how one man helped rebuild Medora into the town it is today, with exhibits on the Medora Musical's history. A calm, air-conditioned stop before hitting the road.","stop":"Harold Schafer Heritage Center","time":"12:00 PM – 1:30 PM"},"day":3,"evening":{"cost":"Free, just gas (est.)","description":"If heading east, detour onto the Enchanted Highway near Gladstone to see giant roadside metal sculptures like Geese in Flight. A fun final photo stop for the family album.","stop":"Drive home via the Enchanted Highway (optional detour)","time":"3:00 PM – 5:00 PM"},"morning":{"cost":"Free (est.)","description":"A quick drive east on I-94 brings you to this overlook with sweeping views of the painted badlands. The short nature trail below the rim is perfect for a morning leg-stretch before checkout.","stop":"Painted Canyon Visitor Center","time":"9:00 AM – 11:00 AM"},"title":"Canyons & Farewell"}],"lat":46.91374,"lng":-103.52584,"overview":"Medora is North Dakota's little Old West town, tucked into the painted badlands where Theodore Roosevelt fell in love with the frontier. Families come for bison sightings in the national park, the famous outdoor Medora Musical, and cowboy history on every corner. Days are full but easygoing, with short drives between sights. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Theodore Roosevelt National Park Visitor Center (film + exhibits)","North Dakota Cowboy Hall of Fame","Harold Schafer Heritage Center"],"region":"Badlands & Western ND","related":["black-hills-sd-mountains","badlands-sd-park","devils-tower-wy-monument"],"restaurants":[{"detail":"Steaks and comfort food in the historic Rough Riders Hotel.","name":"Theodore's Dining Room","price":"$$"},{"detail":"Casual burgers and live music on the main strip.","name":"Boots Bar & Grill","price":"$"},{"detail":"Hearty breakfasts and old-fashioned malts, a Medora staple.","name":"Cowboy Cafe","price":"$"}],"state":"ND","stateName":"North Dakota","tagline":"Painted badlands, bison herds, and a rootin'-tootin' musical under the stars.","title":"Medora, ND: Three-Day Badlands Adventure","tripType":"badlands adventure","imageAsset":"assets/plains-north/images/medora-nd-badlands/hero.jpg"},{"attractions":[{"description":"A 33-acre zoo specializing in animals from cold climates around the world, including red pandas, Pallas's cats, and gray wolves. The shaded paths, carousel, and train make it an easy half-day with kids. Seasonal events like Boo at the Zoo draw big crowds.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Red%20River%20Zoo%20Fargo%20ND","name":"Red River Zoo","officialUrl":"https://redriverzoo.org/","photos":["assets/plains-north/images/fargo-nd-city/attr1-1.jpg","assets/plains-north/images/fargo-nd-city/attr1-2.jpg","assets/plains-north/images/fargo-nd-city/attr1-3.jpg","assets/plains-north/images/fargo-nd-city/attr1-4.jpg"],"price":"$11/adult, $8/child (est.)"},{"description":"An aviation museum in a hangar at Hector International Airport with flyable vintage aircraft, from WWII fighters to crop dusters. Kids can climb into cockpits, try simulators, and explore the hands-on discovery room. Volunteer docents add great stories.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fargo%20Air%20Museum%20Fargo%20ND","name":"Fargo Air Museum","officialUrl":"https://fargoairmuseum.org/","photos":["assets/plains-north/images/fargo-nd-city/attr2-1.jpg","assets/plains-north/images/fargo-nd-city/attr2-2.jpg","assets/plains-north/images/fargo-nd-city/attr2-3.jpg","assets/plains-north/images/fargo-nd-city/attr2-4.jpg"],"price":"$12/adult, $7/child (est.)"},{"description":"The largest art museum in North Dakota, with strong holdings in Native American and regional contemporary art. Admission is free, the building is beautiful, and the family art studio offers creative breaks. Downtown location makes it easy to pair with lunch.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Plains%20Art%20Museum%20Fargo%20ND","name":"Plains Art Museum","officialUrl":"https://plainsart.org/","photos":["assets/plains-north/images/fargo-nd-city/attr3-1.jpg","assets/plains-north/images/fargo-nd-city/attr3-2.jpg","assets/plains-north/images/fargo-nd-city/attr3-3.jpg","assets/plains-north/images/fargo-nd-city/attr3-4.jpg"],"price":"Free (est.)"},{"description":"A 12-acre pioneer village in West Fargo with more than 40 historic buildings, including North Dakota's first courthouse. Costumed guides, antique autos, and a one-room schoolhouse give kids a vivid taste of 1800s prairie life. Open seasonally, roughly May through September.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bonanzaville%20USA%20West%20Fargo%20ND","name":"Bonanzaville USA","officialUrl":"https://www.bonanzaville.org/","photos":["assets/plains-north/images/fargo-nd-city/attr4-1.jpg","assets/plains-north/images/fargo-nd-city/attr4-2.jpg","assets/plains-north/images/fargo-nd-city/attr4-3.jpg","assets/plains-north/images/fargo-nd-city/attr4-4.jpg"],"price":"$12/adult, $6/child (est.)"}],"bestSeason":"May–October","budget":600,"budgetNote":"Estimate for 2 adults + 2 kids: attraction tickets, meals, and parking; lodging not included.","days":2,"destination":"Fargo, ND","driveNotes":"Fargo sits on I-94 at the Minnesota border, about 4 hours from the Twin Cities and 3.5 from Bismarck. Everything on this itinerary is within a 15-minute drive. Downtown parking is easy and mostly free on weekends; winter visitors should pack serious cold-weather gear.","familyFriendly":"Best for ages 4+. Everything is stroller-friendly and drives are short across the metro.","heroPhoto":"assets/plains-north/images/fargo-nd-city/hero.jpg","highlights":["Feed giraffes and ride the carousel at the Red River Zoo","See the real woodchipper from the movie Fargo at the visitor center","Climb inside vintage planes at the Fargo Air Museum","Wander 1800s buildings at Bonanzaville pioneer village","Browse free world-class art at the Plains Art Museum"],"id":"fargo-nd-city","interests":["family","museums","food"],"itinerary":[{"afternoon":{"cost":"$12/adult, $7/child (est.)","description":"Vintage aircraft, a hands-on kids' zone, and flight simulators fill this hangar museum near the airport. Volunteers love telling flying stories, and kids can sit in several cockpits.","stop":"Fargo Air Museum","time":"1:30 PM – 3:30 PM"},"day":1,"evening":{"cost":"Free to explore (est.)","description":"Stroll Broadway for dinner, then snap a photo under the restored Fargo Theatre marquee. Stop by the visitor center to see the actual woodchipper prop from the movie Fargo — kids get a kick out of it.","stop":"Downtown Fargo & the Fargo Theatre marquee","time":"5:00 PM – 7:30 PM"},"morning":{"cost":"$11/adult, $8/child (est.)","description":"This 33-acre zoo is known for its red pandas, gray wolves, and a fun North American prairie exhibit. The carousel and train ride are big hits with younger kids. Plan 2–3 hours at a relaxed pace.","stop":"Red River Zoo","time":"9:30 AM – 12:30 PM"},"title":"Animals & Aviation"},{"afternoon":{"cost":"$12/adult, $6/child (est.)","description":"This pioneer village in West Fargo has 40+ historic buildings, including a church, schoolhouse, and general store. Costumed interpreters and antique cars make history feel real. Great for burning off energy outdoors.","stop":"Bonanzaville USA","time":"1:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Head back downtown for an early dinner at a family favorite, then grab ice cream before the drive home. Fargo's downtown stays lively into the evening in summer.","stop":"Dinner downtown and farewell","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"Free (est.)","description":"North Dakota's largest art museum offers free admission and a bright, welcoming space for families. The Native American and regional collections spark good conversations with older kids. The hands-on art studio is a bonus.","stop":"Plains Art Museum","time":"10:00 AM – 12:00 PM"},"title":"Art & Pioneer Days"}],"lat":46.87591,"lng":-96.78176,"overview":"Fargo surprises families with how much there is to do — a well-loved zoo, a free art museum, vintage aircraft you can climb around, and a pioneer village in neighboring West Fargo. Downtown is compact and walkable, with kid-approved restaurants everywhere. Two days covers the highlights without rushing. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Plains Art Museum","Fargo Air Museum","Children's Museum at Yunker Farm"],"region":"Red River Valley","related":["bismarck-nd-capital","jamestown-nd-frontier","sioux-falls-sd-city"],"restaurants":[{"detail":"Fun, frog-themed spot with great burgers and a kids' menu downtown.","name":"The Toasted Frog","price":"$$"},{"detail":"Lively German beer hall with sausages, pretzels, and polka vibes.","name":"Wurst Bier Hall","price":"$"},{"detail":"Scandinavian-Jewish deli with bagels, latkes, and lefse downtown.","name":"BernBaum's","price":"$"}],"state":"ND","stateName":"North Dakota","tagline":"A friendly prairie city with a great zoo, cool museums, and a movie-famous woodchipper.","title":"Fargo, ND: Two-Day City Getaway","tripType":"city getaway","imageAsset":"assets/plains-north/images/fargo-nd-city/hero.jpg"},{"attractions":[{"description":"The state's largest museum, free to enter, with standout galleries on dinosaurs, ice age mammals, and 10,000 years of Native American history. Real fossils pulled from North Dakota badlands anchor the dino hall. Plan at least half a day — families consistently call it the trip highlight.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=North%20Dakota%20Heritage%20Center%20Bismarck%20ND","name":"North Dakota Heritage Center & State Museum","officialUrl":"https://www.history.nd.gov/","photos":["assets/plains-north/images/bismarck-nd-capital/attr1-1.jpg","assets/plains-north/images/bismarck-nd-capital/attr1-2.jpg","assets/plains-north/images/bismarck-nd-capital/attr1-3.jpg","assets/plains-north/images/bismarck-nd-capital/attr1-4.jpg"],"price":"Free (est.)"},{"description":"A 90-acre riverside zoo with more than 600 mammals, birds, and reptiles, from tigers to penguins. The miniature train, carousel, and big picnic lawns make it ideal for a half-day family outing. Seasonal hours run roughly May through September.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dakota%20Zoo%20Bismarck%20ND","name":"Dakota Zoo","officialUrl":"https://dakotazoo.org/","photos":["assets/plains-north/images/bismarck-nd-capital/attr2-1.jpg","assets/plains-north/images/bismarck-nd-capital/attr2-2.jpg","assets/plains-north/images/bismarck-nd-capital/attr2-3.jpg","assets/plains-north/images/bismarck-nd-capital/attr2-4.jpg"],"price":"$13/adult, $9/child (est.)"},{"description":"An authentic sternwheel riverboat offering narrated sightseeing cruises on the Missouri River from the Bismarck riverfront. The open decks are perfect for eagle-spotting and bluff views. Dinner and themed cruises run select evenings in summer.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lewis%20and%20Clark%20Riverboat%20Bismarck%20ND","name":"Lewis & Clark Riverboat","officialUrl":"https://lewisandclarkriverboat.com/","photos":["assets/plains-north/images/bismarck-nd-capital/attr3-1.jpg","assets/plains-north/images/bismarck-nd-capital/attr3-2.jpg","assets/plains-north/images/bismarck-nd-capital/attr3-3.jpg","assets/plains-north/images/bismarck-nd-capital/attr3-4.jpg"],"price":"$28/adult, $14/child (est.)"},{"description":"In Mandan, across the river, this park preserves the frontier army post where Custer rode out in 1876. Tour the reconstructed Custer House, barracks, and the On-A-Slant earthlodge village. Summer interpreters in period dress make history tangible for kids.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fort%20Abraham%20Lincoln%20State%20Park%20Mandan%20ND","name":"Fort Abraham Lincoln State Park","officialUrl":"https://www.parkrec.nd.gov/","photos":["assets/plains-north/images/bismarck-nd-capital/attr4-1.jpg","assets/plains-north/images/bismarck-nd-capital/attr4-2.jpg","assets/plains-north/images/bismarck-nd-capital/attr4-3.jpg","assets/plains-north/images/bismarck-nd-capital/attr4-4.jpg"],"price":"$9/vehicle (est.)"}],"bestSeason":"May–October","budget":850,"budgetNote":"Estimate for 2 adults + 2 kids: attraction tickets, a riverboat cruise, meals, and gas; lodging not included.","days":3,"destination":"Bismarck, ND","driveNotes":"Bismarck is on I-94 in central North Dakota, about 3.5 hours from Fargo and 2 from Medora. The riverboat dock, zoo, and capitol are all within 15 minutes of each other. Fort Abraham Lincoln is a 10-minute drive into Mandan across the river — an easy add-on day.","familyFriendly":"Best for ages 4+. Museums are stroller-friendly; the riverboat has open decks kids love.","heroPhoto":"assets/plains-north/images/bismarck-nd-capital/hero.jpg","highlights":["Explore dinosaur fossils at the free Heritage Center museum","Cruise the Missouri River on the Lewis & Clark Riverboat","Meet 600+ animals at the Dakota Zoo","Tour Custer's house at Fort Abraham Lincoln State Park","Watch the sunset from the riverfront walking trails"],"id":"bismarck-nd-capital","interests":["family","museums","outdoors","historical-sites"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Walk next door for a free guided tour of the 19-story art-deco capitol — the tallest building in the state. The observation deck views stretch for miles over the prairie. Tours run on the hour in summer.","stop":"North Dakota State Capitol tour","time":"1:30 PM – 3:00 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Head downtown for dinner along Main Avenue, where family-friendly restaurants cluster. An evening stroll past the historic Patterson Hotel area caps a full first day.","stop":"Downtown Bismarck dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Free (est.)","description":"Start at this excellent free museum next to the capitol. The dinosaur gallery, with real fossils found in the state, mesmerizes kids, and the ice age and Native American exhibits are top-notch. Give it at least 2–3 hours.","stop":"North Dakota Heritage Center & State Museum","time":"9:30 AM – 12:30 PM"},"title":"Dinosaurs & Discovery"},{"afternoon":{"cost":"$28/adult, $14/child (est.)","description":"Board this authentic sternwheeler for a narrated cruise on the Missouri River. Kids love the open upper deck and spotting eagles along the bluffs. Cruises run afternoons in summer — book ahead on weekends.","stop":"Lewis & Clark Riverboat cruise","time":"2:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free (est.)","description":"Walk or bike the paved trails along the river as the sun drops. Playgrounds and open lawns let kids burn off the last of the day's energy.","stop":"Riverfront trails at Sertoma Park","time":"5:30 PM – 7:00 PM"},"morning":{"cost":"$13/adult, $9/child (est.)","description":"This 90-acre zoo on the river is home to over 600 animals, including big cats, primates, and penguins. The train ride and shaded picnic areas make it a relaxed morning for families.","stop":"Dakota Zoo","time":"9:30 AM – 12:30 PM"},"title":"Zoo & Riverboat"},{"afternoon":{"cost":"$40–$60 for lunch (est.)","description":"Grab lunch in Mandan's historic downtown, then browse the antique shops before heading home. If time allows, stop at the Five Nations Arts shop for Native-made souvenirs.","stop":"Downtown Mandan & farewell","time":"1:00 PM – 3:00 PM"},"day":3,"evening":{"cost":"Gas only (est.)","description":"An easy afternoon departure gets you home for dinner if you're within a few hours. Otherwise, linger for one more riverfront sunset.","stop":"Drive home","time":"3:30 PM – 6:00 PM"},"morning":{"cost":"$9/vehicle park entry (est.)","description":"Cross the river to Mandan to tour the reconstructed Custer House, where General Custer lived before Little Bighorn. The On-A-Slant Mandan village with its earthlodges fascinates kids, and costumed guides bring it alive.","stop":"Fort Abraham Lincoln State Park","time":"9:30 AM – 12:30 PM"},"title":"Frontier Forts"}],"lat":46.80536,"lng":-100.77969,"overview":"North Dakota's capital pairs big history with easy family fun on the Missouri River. The free Heritage Center museum could fill a whole day, the Dakota Zoo delights younger kids, and a riverboat cruise gives everyone a breezy afternoon. Nearby Mandan adds a reconstructed frontier fort and Custer's last home. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["North Dakota Heritage Center & State Museum","Raging Rivers Waterpark (indoor)","Gateway Mall (shopping + play areas)"],"region":"Missouri River Valley","related":["fargo-nd-city","medora-nd-badlands","jamestown-nd-frontier"],"restaurants":[{"detail":"Downtown favorite with a great kids' menu and patio.","name":"Peacock Alley American Grill & Bar","price":"$$"},{"detail":"Eclectic, artsy spot known for creative comfort food.","name":"The Walrus Restaurant","price":"$$"},{"detail":"Wood-fired pizzas the whole family will devour.","name":"Fireflour Pizza","price":"$"}],"state":"ND","stateName":"North Dakota","tagline":"Lewis and Clark country — a free world-class museum, a riverboat cruise, and frontier forts.","title":"Bismarck, ND: Three-Day Capital & River Adventure","tripType":"river adventure","imageAsset":"assets/plains-north/images/bismarck-nd-capital/hero.jpg"},{"attractions":[{"description":"The main state park on Devils Lake, with a sandy swimming beach, modern campgrounds, and a fishing pier. It's the go-to family base for lake days, with playgrounds and picnic shelters under the cottonwoods. About 10 miles from town.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Grahams%20Island%20State%20Park%20Devils%20Lake%20ND","name":"Grahams Island State Park","officialUrl":"https://www.parkrec.nd.gov/","photos":["assets/plains-north/images/devils-lake-nd-lakeside/attr1-1.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr1-2.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr1-3.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr1-4.jpg"],"price":"$7/vehicle day pass (est.)"},{"description":"A 1,674-acre national wildlife refuge on the shores of Devils Lake, home to bison, elk, white-tailed deer, and prairie dogs. The 4-mile auto tour and short hiking trails make wildlife viewing easy for all ages. The visitor center explains the preserve's conservation story.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sullys%20Hill%20National%20Game%20Preserve%20Devils%20Lake%20ND","name":"Sullys Hill National Game Preserve","officialUrl":"https://www.fws.gov/refuge/sullys-hill","photos":["assets/plains-north/images/devils-lake-nd-lakeside/attr2-1.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr2-2.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr2-3.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr2-4.jpg"],"price":"Free (est.)"},{"description":"Built in 1867, Fort Totten is one of the most intact frontier military posts in America, with 16 original buildings. Summer living-history programs demonstrate blacksmithing, baking, and soldier life. The site also interprets its later years as an Indian boarding school.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fort%20Totten%20State%20Historic%20Site%20Fort%20Totten%20ND","name":"Fort Totten State Historic Site","officialUrl":"https://www.history.nd.gov/historicsites/totten/","photos":["assets/plains-north/images/devils-lake-nd-lakeside/attr3-1.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr3-2.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr3-3.jpg","assets/plains-north/images/devils-lake-nd-lakeside/attr3-4.jpg"],"price":"$8/adult, $4/child 6–15 (est.)"}],"bestSeason":"June–September","budget":800,"budgetNote":"Estimate for 2 adults + 2 kids: park entries, a fishing outing, meals, and gas; lodging not included.","days":3,"destination":"Devils Lake, ND","driveNotes":"Devils Lake is on US-2 in northeastern North Dakota, about 90 minutes west of Grand Forks and 3 hours from Fargo. Grahams Island is a 15-minute drive south of town; Sullys Hill and Fort Totten are about 20 minutes southeast. Cell service can be spotty around the lake — download maps offline.","familyFriendly":"Best for ages 5+. Lake beaches are gentle; bring bug spray for summer evenings.","heroPhoto":"assets/plains-north/images/devils-lake-nd-lakeside/hero.jpg","highlights":["Swim and picnic at Grahams Island State Park's sandy beach","Drive the auto tour past bison and elk at Sullys Hill","Tour the 1867 frontier buildings at Fort Totten","Try a family fishing outing for walleye and perch","Watch pelicans and sunsets over the big lake"],"id":"devils-lake-nd-lakeside","interests":["family","outdoors","nature","historical-sites"],"itinerary":[{"afternoon":{"cost":"Free with park pass; fishing license ~$18/adult (est.)","description":"Try the fishing pier after lunch — perch bite readily and kids love the action. Pack a simple picnic or grab snacks from the park. Keep an eye out for white pelicans gliding over the water.","stop":"More lake time & fishing pier","time":"2:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"Free (est.)","description":"Devils Lake sunsets over open water are spectacular. Bring a blanket and let the kids skip stones while the sky turns orange.","stop":"Sunset at the lake","time":"7:30 PM – 8:30 PM"},"morning":{"cost":"$7/vehicle day pass (est.)","description":"Set up for a classic lake day: sandy swimming beach, playgrounds, and shaded picnic shelters. The water warms up nicely by July. Rent a kayak or just splash around — the shallow entry is great for little kids.","stop":"Grahams Island State Park","time":"10:00 AM – 1:00 PM"},"title":"Beach Day"},{"afternoon":{"cost":"$8/adult, kids 6–15 $4 (est.)","description":"One of the best-preserved frontier forts in the West, with 16 original 1867 buildings. Summer interpreters demonstrate blacksmithing and frontier life, and the on-site pioneer museum adds depth for older kids.","stop":"Fort Totten State Historic Site","time":"1:00 PM – 3:30 PM"},"day":2,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Head back to town for a lakeside dinner and an early night. Summer evenings are long this far north — perfect for one more stroll by the water.","stop":"Dinner in Devils Lake","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Free (est.)","description":"This 1,600-acre preserve near Fort Totten protects bison, elk, and prairie dogs. Drive the 4-mile auto tour slowly — bison often graze right by the road. The visitor center has kid-friendly exhibits.","stop":"Sullys Hill National Game Preserve","time":"9:00 AM – 11:30 AM"},"title":"Wildlife & Frontier"},{"afternoon":{"cost":"Small donation (est.)","description":"This local museum in downtown Devils Lake covers pioneer life, the railroad era, and the lake's famous floods. A quiet, cool stop before the drive home.","stop":"Lake Region Heritage Center","time":"1:30 PM – 3:00 PM"},"day":3,"evening":{"cost":"Gas only (est.)","description":"Devils Lake is about 90 minutes west of Grand Forks on US-2. An afternoon departure gets most families home by dinner.","stop":"Drive home","time":"3:30 PM – 5:30 PM"},"morning":{"cost":"$150–$250 for a half-day guide (est.)","description":"Book a half-day guided trip or fish from shore — Devils Lake is one of the top perch and walleye lakes in the country. Guides provide gear and clean your catch. Even beginners usually land fish here.","stop":"Family fishing outing","time":"8:00 AM – 12:00 PM"},"title":"Fishing & Farewell"}],"lat":48.11253,"lng":-98.85728,"overview":"Devils Lake is a sprawling prairie lake famous for walleye and perch fishing, with sandy beaches and state parks made for family days. Nearby, a national game preserve protects bison and elk, and Fort Totten tells the story of the frontier era. It's a slower, outdoorsy trip — perfect for families who'd rather cast a line than stand in line. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Lake Region Heritage Center","Burke Theatre (historic movie house)","Spirit Lake Casino's event center (family shows, seasonal)"],"region":"Lake Region","related":["fargo-nd-city","bismarck-nd-capital","jamestown-nd-frontier"],"restaurants":[{"detail":"Lakeside dining with walleye and burgers right on the water.","name":"Proz Lakeside at the Cove","price":"$$"},{"detail":"Classic small-town cafe with hearty breakfasts and pies.","name":"Old Main Street Cafe","price":"$"},{"detail":"Historic supper club known for steaks, walleye, and famous popovers.","name":"Ranch Steakhouse","price":"$$"}],"state":"ND","stateName":"North Dakota","tagline":"North Dakota's biggest natural lake — fishing, beaches, bison, and frontier forts.","title":"Devils Lake, ND: Three-Day Lakeside Escape","tripType":"lakeside escape","imageAsset":"assets/plains-north/images/devils-lake-nd-lakeside/hero.jpg"},{"attractions":[{"description":"Dedicated to the history and future of the American bison, with exhibits on the great herds, the near-extinction, and restoration. Outside you'll find a live bison herd and Dakota Thunder, the World's Largest Buffalo statue at 26 feet tall. A must-stop photo op on I-94.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=National%20Buffalo%20Museum%20Jamestown%20ND","name":"National Buffalo Museum","officialUrl":"https://www.buffalomuseum.com/","photos":["assets/plains-north/images/jamestown-nd-frontier/attr1-1.jpg","assets/plains-north/images/jamestown-nd-frontier/attr1-2.jpg","assets/plains-north/images/jamestown-nd-frontier/attr1-3.jpg","assets/plains-north/images/jamestown-nd-frontier/attr1-4.jpg"],"price":"$12/adult, $4/child (est.)"},{"description":"A recreated 1880s prairie town with more than 20 historic buildings moved in from across the region — saloon, church, schoolhouse, and all. Costumed interpreters and summer events make it lively, and admission is free. Shares a hilltop with the World's Largest Buffalo.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Frontier%20Village%20Jamestown%20ND","name":"Frontier Village","officialUrl":"https://www.buffalomuseum.com/","photos":["assets/plains-north/images/jamestown-nd-frontier/attr2-1.jpg","assets/plains-north/images/jamestown-nd-frontier/attr2-2.jpg","assets/plains-north/images/jamestown-nd-frontier/attr2-3.jpg","assets/plains-north/images/jamestown-nd-frontier/attr2-4.jpg"],"price":"Free; donations welcome (est.)"},{"description":"A 2,000-acre reservoir just north of town with a swimming beach, boat ramps, and picnic areas. Families come for easy swimming, fishing for walleye and bass, and calm-water kayaking. The surrounding trails are great for an evening walk.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Jamestown%20Reservoir%20Jamestown%20ND","name":"Jamestown Reservoir","officialUrl":"https://www.discoverjamestownnd.com/","photos":["assets/plains-north/images/jamestown-nd-frontier/attr3-1.jpg","assets/plains-north/images/jamestown-nd-frontier/attr3-2.jpg","assets/plains-north/images/jamestown-nd-frontier/attr3-3.jpg","assets/plains-north/images/jamestown-nd-frontier/attr3-4.jpg"],"price":"Free access (est.)"}],"bestSeason":"May–September","budget":500,"budgetNote":"Estimate for 2 adults + 2 kids: museum tickets, meals, and gas; lodging not included.","days":2,"destination":"Jamestown, ND","driveNotes":"Jamestown is directly on I-94, 90 minutes from both Fargo and Bismarck — ideal as a stopover or easy weekend. The Buffalo Museum and Frontier Village sit on a hill just off the interstate with big signs you can't miss. The reservoir is 5 miles north of town on paved roads.","familyFriendly":"Best for ages 4+. Short walks, big photo ops, and plenty of open space for wiggly kids.","heroPhoto":"assets/plains-north/images/jamestown-nd-frontier/hero.jpg","highlights":["Pose with Dakota Thunder, the World's Largest Buffalo","Meet a live bison herd at the National Buffalo Museum","Wander the 1800s buildings of Frontier Village","Swim and picnic at Jamestown Reservoir","Walk the trails of the Pipestem Creek area"],"id":"jamestown-nd-frontier","interests":["family","historical-sites","outdoors"],"itinerary":[{"afternoon":{"cost":"Free; donations welcome (est.)","description":"Right next door, this recreated 1800s prairie town has two dozen historic buildings, including a barber shop, bank, and one-room schoolhouse. Summer weekends bring artisans and live demonstrations. It's shady and easy to wander.","stop":"Frontier Village","time":"1:00 PM – 3:30 PM"},"day":1,"evening":{"cost":"$40–$60 for dinner (est.)","description":"Dinner downtown, then a stroll past the historic Opera House and the world's largest buffalo statue lit up at night. A low-key evening after a full day.","stop":"Downtown Jamestown","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"$12/adult, $4/child (est.)","description":"Start with the museum's exhibits on bison history and the Northern Plains, then head outside to meet the live bison herd. The star, of course, is Dakota Thunder — the 26-foot concrete buffalo you can see from I-94. Kids love the photo ops.","stop":"National Buffalo Museum","time":"9:30 AM – 12:00 PM"},"title":"Buffalo Country"},{"afternoon":{"cost":"Free (est.)","description":"Back in town, visit The Arts Center's galleries and browse the antique shops along Main Street. A relaxed final stop before hitting I-94.","stop":"The Arts Center & downtown shops","time":"2:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"Gas only (est.)","description":"Jamestown sits right on I-94, about 90 minutes west of Fargo and 90 minutes east of Bismarck — an easy afternoon departure either way.","stop":"Drive home","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free access (est.)","description":"Head north of town for a morning at the reservoir's swimming beach and picnic areas. The water is calm, the beach is sandy, and there's a playground for younger kids. Bring a picnic lunch.","stop":"Jamestown Reservoir","time":"10:00 AM – 1:00 PM"},"title":"Reservoir Day"}],"lat":46.91032,"lng":-98.70854,"overview":"Jamestown is the classic I-94 road-trip stop, anchored by the famous 26-foot-tall buffalo statue and the National Buffalo Museum. The adjacent Frontier Village recreates an 1800s prairie town, and the nearby reservoir offers beaches and boating. It's a compact, affordable two-day trip that pairs well with Fargo or Bismarck. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["National Buffalo Museum","The Arts Center (galleries + classes)","Jamestown Civic Center (open gym, seasonal)"],"region":"James River Valley","related":["fargo-nd-city","bismarck-nd-capital","devils-lake-nd-lakeside"],"restaurants":[{"detail":"Wood-fired pizza and wings in a restored 1800s brick building.","name":"Jonny B's Brickhouse","price":"$$"},{"detail":"Beloved local cafe with hearty breakfasts and famous caramel rolls.","name":"The Depot Cafe","price":"$"},{"detail":"Family pizza-and-chicken buffet the kids will love.","name":"Pizza Ranch","price":"$"}],"state":"ND","stateName":"North Dakota","tagline":"Home of the World's Largest Buffalo — a perfect overnight on your prairie road trip.","title":"Jamestown, ND: Two-Day Frontier Stop","tripType":"frontier stop","imageAsset":"assets/plains-north/images/jamestown-nd-frontier/hero.jpg"},{"attractions":[{"description":"America's most famous mountain carving, where four presidents gaze over the Black Hills from a 60-foot scale. The Avenue of Flags, ranger talks, and the evening lighting ceremony give the visit depth beyond the photo. Go early or late to beat the crowds.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mount%20Rushmore%20National%20Memorial%20Keystone%20SD","name":"Mount Rushmore National Memorial","officialUrl":"https://www.nps.gov/moru/","photos":["assets/plains-north/images/black-hills-sd-mountains/attr1-1.jpg","assets/plains-north/images/black-hills-sd-mountains/attr1-2.jpg","assets/plains-north/images/black-hills-sd-mountains/attr1-3.jpg","assets/plains-north/images/black-hills-sd-mountains/attr1-4.jpg"],"price":"Free; parking $10/vehicle (est.)"},{"description":"Still being carved, this colossal mountain sculpture honors Crazy Horse and Native American heritage. The Indian Museum of North America and university campus on-site add real cultural depth. Families can ride up to the arm of the mountain on the summer bus.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Crazy%20Horse%20Memorial%20Crazy%20Horse%20SD","name":"Crazy Horse Memorial","officialUrl":"https://crazyhorsememorial.org/","photos":["assets/plains-north/images/black-hills-sd-mountains/attr2-1.jpg","assets/plains-north/images/black-hills-sd-mountains/attr2-2.jpg","assets/plains-north/images/black-hills-sd-mountains/attr2-3.jpg","assets/plains-north/images/black-hills-sd-mountains/attr2-4.jpg"],"price":"$35/vehicle (est.)"},{"description":"One of the world's longest caves, with delicate honeycomb boxwork found almost nowhere else. The 1-hour Discovery Tour is easy and family-friendly; older kids may like the wilder candlelight tours. Tours sell out — book online well ahead.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wind%20Cave%20National%20Park%20Hot%20Springs%20SD","name":"Wind Cave National Park","officialUrl":"https://www.nps.gov/wica/","photos":["assets/plains-north/images/black-hills-sd-mountains/attr3-1.jpg","assets/plains-north/images/black-hills-sd-mountains/attr3-2.jpg","assets/plains-north/images/black-hills-sd-mountains/attr3-3.jpg","assets/plains-north/images/black-hills-sd-mountains/attr3-4.jpg"],"price":"$14/adult cave tour, kids 5 and under free (est.)"},{"description":"A wildly fun 14-mile drive through pine forests, granite tunnels, and hairpin pigtail bridges. Start in Custer and wind down to Mount Rushmore — the tunnels perfectly frame the presidents' faces at the end. Allow an hour, not counting photo stops.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Iron%20Mountain%20Road%20Keystone%20SD","name":"Iron Mountain Road","officialUrl":"https://www.nps.gov/moru/","photos":["assets/plains-north/images/black-hills-sd-mountains/attr4-1.jpg","assets/plains-north/images/black-hills-sd-mountains/attr4-2.jpg","assets/plains-north/images/black-hills-sd-mountains/attr4-3.jpg","assets/plains-north/images/black-hills-sd-mountains/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"May–October","budget":1200,"budgetNote":"Estimate for 2 adults + 2 kids: attraction tickets, meals, and gas; lodging not included.","days":4,"destination":"Black Hills, SD","driveNotes":"Base in Keystone or Hill City to be central — Rushmore, Crazy Horse, and Custer are all within 30 minutes. Iron Mountain Road and Needles Highway are narrow with one-lane tunnels; take them slow. Summer weekends are busy, so buy cave tickets and book restaurants ahead.","familyFriendly":"Best for ages 5+. The scenic drives thrill kids; cave tours need a 3+ age for some routes — check when booking.","heroPhoto":"assets/plains-north/images/black-hills-sd-mountains/hero.jpg","highlights":["See four presidents carved into Mount Rushmore","Watch sculptors at work on the Crazy Horse mountain","Descend into Wind Cave's rare boxwork passages","Drive Iron Mountain Road's pigtail bridges and tunnels","Ride a historic train between Hill City and Keystone"],"id":"black-hills-sd-mountains","interests":["family","nature","scenic","historical-sites","outdoors"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Drive Iron Mountain Road from Custer toward Keystone — the one-lane tunnels and pigtail bridges are an adventure in themselves. The tunnels frame Mount Rushmore's faces at the perfect moment. Stop at the Peter Norbeck overlook for photos.","stop":"Iron Mountain Road scenic drive","time":"1:30 PM – 4:00 PM"},"day":1,"evening":{"cost":"Free (est.)","description":"Return after dinner for the evening lighting ceremony, when the memorial glows against the night sky. It's patriotic, moving, and a highlight for kids. Bring a jacket — it gets cool after sunset.","stop":"Mount Rushmore evening lighting ceremony","time":"8:30 PM – 9:30 PM"},"morning":{"cost":"$10 parking (est.)","description":"Arrive early to walk the Avenue of Flags and the Presidential Trail before the crowds. Rangers lead short talks kids enjoy, and the sculptor's studio shows how the carving was done. Budget 3 hours.","stop":"Mount Rushmore National Memorial","time":"9:00 AM – 12:00 PM"},"title":"The Faces on the Mountain"},{"afternoon":{"cost":"$30–$45 for train tickets (est.)","description":"Ride the historic 1880 Train between Hill City and Keystone through old mining country. The open-air cars are a hit with kids, and the depot towns are fun to browse.","stop":"1880 Train ride","time":"2:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free to browse (est.)","description":"Hill City's main street has rock shops, ice cream, and family restaurants. The town feels like the old west with a modern twist — perfect for a relaxed evening.","stop":"Dinner in Hill City","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$35/vehicle (est.)","description":"This mountain carving-in-progress dwarfs Rushmore in scale and tells the story of Native American heritage. The museum, university, and summer bus ride to the base make it a rich half-day. Allow 3 hours.","stop":"Crazy Horse Memorial","time":"9:00 AM – 12:00 PM"},"title":"Crazy Horse & the 1880 Train"},{"afternoon":{"cost":"$60–$90 for the family (est.)","description":"Head to Keystone for the Alpine Slide or the Rushmore Tramway — gravity-fed thrills with mountain views. Younger kids love the Aerial Adventure Park's ropes courses.","stop":"Keystone attractions","time":"2:00 PM – 5:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Grab dinner in Keystone and browse the souvenir shops. The town stays lively in summer with fudge shops and old-time photo studios.","stop":"Dinner and shops in Keystone","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"$14/adult cave tour (est.)","description":"Head south to explore one of the world's longest caves, famous for its rare honeycomb boxwork. The easy Discovery Tour suits families; book tickets online in advance since tours sell out.","stop":"Wind Cave National Park","time":"9:00 AM – 12:30 PM"},"title":"Caves & Keystone Fun"},{"afternoon":{"cost":"Free (est.)","description":"Drive the Needles Highway through Custer State Park on your way out — granite spires, more one-lane tunnels, and great picnic spots. A fitting final Black Hills adventure.","stop":"Needles Highway drive (optional)","time":"1:00 PM – 3:00 PM"},"day":4,"evening":{"cost":"Gas only (est.)","description":"From Keystone, Rapid City is 25 minutes and I-90 east is an easy on-ramp. Depart in the late afternoon for dinner on the road.","stop":"Drive home","time":"3:30 PM – 5:30 PM"},"morning":{"cost":"Free (est.)","description":"A relaxed final morning: pancakes in Keystone and one last look at the mountain from the highway pullouts. Pick up souvenirs for the road.","stop":"Farewell breakfast in Keystone","time":"9:00 AM – 11:00 AM"},"title":"Farewell Drive"}],"lat":43.89369,"lng":-103.42428,"overview":"The Black Hills pack America's most famous mountain carving, an even bigger one still being built, wild caves, and the country's most fun scenic drives into a compact area. Base in Keystone or Hill City and everything is under 30 minutes away. Four days lets you see it all without rushing the kids. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Crazy Horse Memorial's Indian Museum of North America","The Journey Museum & Learning Center (Rapid City)","Museum of Geology (Rapid City, free)"],"region":"Black Hills","related":["custer-sd-wildlife","badlands-sd-park","deadwood-sd-wildwest"],"restaurants":[{"detail":"Legendary spot near Rushmore with game meats and family platters.","name":"Powder House Lodge","price":"$$"},{"detail":"Hill City favorite with burgers, steaks, and a kids' menu.","name":"Alpine Inn","price":"$$"},{"detail":"Old West steakhouse with buffalo stew in a bread bowl, 2 miles from Rushmore.","name":"Ruby House Restaurant","price":"$$"}],"state":"SD","stateName":"South Dakota","tagline":"Presidents on a mountain, caves below, and the wildest scenic drives in America.","title":"Black Hills, SD: Four-Day Mountain Adventure","tripType":"mountain adventure","imageAsset":"assets/plains-north/images/black-hills-sd-mountains/hero.jpg"},{"attractions":[{"description":"244,000 acres of striped spires, pinnacles, and prairie where bison and bighorn sheep roam. The Badlands Loop Road strings together overlooks, and the Notch, Door, and Window trails are short and spectacular. Sunrise and sunset turn the formations pink and gold.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Badlands%20National%20Park%20Interior%20SD","name":"Badlands National Park","officialUrl":"https://www.nps.gov/badl/","photos":["assets/plains-north/images/badlands-sd-park/attr1-1.jpg","assets/plains-north/images/badlands-sd-park/attr1-2.jpg","assets/plains-north/images/badlands-sd-park/attr1-3.jpg","assets/plains-north/images/badlands-sd-park/attr1-4.jpg"],"price":"$30/vehicle, 7-day pass (est.)"},{"description":"A decommissioned Cold War missile silo and launch control center, preserved as a national historic site. Ranger-led tours descend into the underground control capsule — a powerful, unforgettable lesson for older kids. Tours require reservations and fill fast.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Minuteman%20Missile%20National%20Historic%20Site%20Philip%20SD","name":"Minuteman Missile National Historic Site","officialUrl":"https://www.nps.gov/mimi/","photos":["assets/plains-north/images/badlands-sd-park/attr2-1.jpg","assets/plains-north/images/badlands-sd-park/attr2-2.jpg","assets/plains-north/images/badlands-sd-park/attr2-3.jpg","assets/plains-north/images/badlands-sd-park/attr2-4.jpg"],"price":"Free; tours by reservation (est.)"},{"description":"The famous roadside emporium that's been luring travelers with free ice water since 1931. Beyond the billboards, kids love the animatronic dinosaurs, the western store, and the 5-cent coffee. A joyful, kitschy lunch stop the whole family will remember.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wall%20Drug%20Wall%20SD","name":"Wall Drug","officialUrl":"https://www.walldrug.com/","photos":["assets/plains-north/images/badlands-sd-park/attr3-1.jpg","assets/plains-north/images/badlands-sd-park/attr3-2.jpg","assets/plains-north/images/badlands-sd-park/attr3-3.jpg","assets/plains-north/images/badlands-sd-park/attr3-4.jpg"],"price":"Free entry; food extra (est.)"},{"description":"A working prairie homestead from 1909 with the original sod house, barn, and windmill still standing. Families can walk the grounds, meet farm animals, and see how homesteaders really lived. Just off the Badlands Loop Road near the east entrance.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Prairie%20Homestead%20Badlands%20SD","name":"Prairie Homestead","officialUrl":"https://www.prairiehomestead.com/","photos":["assets/plains-north/images/badlands-sd-park/attr4-1.jpg","assets/plains-north/images/badlands-sd-park/attr4-2.jpg","assets/plains-north/images/badlands-sd-park/attr4-3.jpg","assets/plains-north/images/badlands-sd-park/attr4-4.jpg"],"price":"$10/adult, kids under 6 free (est.)"}],"bestSeason":"May–October","budget":800,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, meals, and gas; lodging not included.","days":3,"destination":"Badlands, SD","driveNotes":"Base in Wall (north entrance) or Interior (south). The Badlands Loop Road (SD-240) is about 39 miles of easy paved driving with constant pullouts. Summer heat is intense — carry lots of water, and do hikes before 11 AM. Rapid City is 60 miles west on I-90 for supplies.","familyFriendly":"Best for ages 6+. Trails are short but exposed — bring hats, sunscreen, and twice the water you think you need.","heroPhoto":"assets/plains-north/images/badlands-sd-park/hero.jpg","highlights":["Watch the spires glow pink at sunrise or sunset","Walk the boardwalk trails of the Door and Window","Tour a real Cold War missile control center","Meet the jackalopes at Wall Drug","Step inside a 1909 sod house at Prairie Homestead"],"id":"badlands-sd-park","interests":["family","nature","scenic","historical-sites","outdoors"],"itinerary":[{"afternoon":{"cost":"$30/vehicle (est.)","description":"Continue the loop to the Ben Reifel Visitor Center, where kids love the fossil exhibits and the prairie dog town right outside. The Notch Trail's ladder climb is thrilling for adventurous older kids.","stop":"Badlands Loop Road, east half","time":"2:00 PM – 5:30 PM"},"day":1,"evening":{"cost":"Free (est.)","description":"Base in Wall for the night. Grab dinner in town and rest up — tomorrow is an early start for the missile tour.","stop":"Dinner in Wall","time":"6:30 PM – 8:00 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Enter via the Pinnacles entrance and drive the loop slowly, stopping at the best overlooks. Walk the short Door, Window, and Notch boardwalk trails — all under a mile and spectacular. Arrive by 9 AM to beat the heat.","stop":"Badlands Loop Road, west half","time":"9:00 AM – 12:30 PM"},"title":"The Loop Road"},{"afternoon":{"cost":"Free (est.)","description":"Step inside an original 1909 sod house and see how homesteaders lived on the prairie. Farm animals and the old barn keep younger kids entertained. It's a quick, memorable stop.","stop":"Prairie Homestead","time":"2:00 PM – 3:30 PM"},"day":2,"evening":{"cost":"Free entry (est.)","description":"The famous Wall Drug: free ice water, 5-cent coffee, a giant jackalope, and shops full of western kitsch. Let the kids pick one souvenir and grab an early dinner before heading back.","stop":"Wall Drug","time":"4:30 PM – 6:30 PM"},"morning":{"cost":"Free; reservation required (est.)","description":"Descend into a real Cold War missile control center on a ranger-led tour (Delta-01). It's a gripping history lesson for older kids and adults. Book weeks ahead — tours fill fast. Note: limited capacity, no young toddlers underground.","stop":"Minuteman Missile National Historic Site","time":"9:30 AM – 11:30 AM"},"title":"Cold War & Kitsch"},{"afternoon":{"cost":"Gas only (est.)","description":"The Sage Creek Rim Road on the park's west side is a gravel drive where bison herds and prairie dog towns are common. The Roberts Prairie Dog Town is a kid favorite. Return to Wall by late afternoon.","stop":"Sage Creek wildlife drive (optional)","time":"1:00 PM – 3:30 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"One more sunset over the formations from the Pinnacles Overlook, then hit I-90. The formations at golden hour are the trip's best photos.","stop":"Sunset farewell","time":"6:00 PM – 7:30 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Rise early for sunrise at the Door Trail — the formations glow pink and orange, and you'll have the trails nearly to yourself. A magical final morning in the park.","stop":"Sunrise at the Door Trail","time":"6:00 AM – 8:00 AM"},"title":"Sunrise & Wildlife"}],"lat":43.79129,"lng":-101.90491,"overview":"The Badlands look like another planet — striped spires and pinnacles rising from the prairie, with bison and bighorn sheep wandering through. It's an easy park for families: the loop road does the work, the trails are short, and Wall Drug adds pure roadside joy. Add a sobering Cold War missile tour for older kids. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Ben Reifel Visitor Center (fossil exhibits + film)","Wall Drug (indoor shops and restaurant)","Wounded Knee: The Museum (Wall)"],"region":"Badlands & Prairie","related":["black-hills-sd-mountains","medora-nd-badlands","custer-sd-wildlife"],"restaurants":[{"detail":"The famous roadside stop's cafe — donuts, buffalo burgers, and 5-cent coffee.","name":"Wall Drug Cafe","price":"$"},{"detail":"Hearty small-town American food near the park's west side.","name":"Circle View Ranch Restaurant","price":"$"},{"detail":"Homemade pies and comfort food on the road to the Badlands.","name":"Red Rock Restaurant","price":"$"}],"state":"SD","stateName":"South Dakota","tagline":"Moon-like spires, roaming bison, a Cold War missile silo, and the world's best roadside drugstore.","title":"Badlands, SD: Three-Day Park Adventure","tripType":"park adventure","imageAsset":"assets/plains-north/images/badlands-sd-park/hero.jpg"},{"attractions":[{"description":"The city's namesake — a stunning series of cascades where the Big Sioux River drops 100 feet through pink quartzite. The Falls Park Visitor Center, observation tower, and lighted falls at night make it a must. Free and beautiful in every season.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Falls%20Park%20Sioux%20Falls%20SD","name":"Falls Park","officialUrl":"https://www.siouxfalls.gov/","photos":["assets/plains-north/images/sioux-falls-sd-city/attr1-1.jpg","assets/plains-north/images/sioux-falls-sd-city/attr1-2.jpg","assets/plains-north/images/sioux-falls-sd-city/attr1-3.jpg","assets/plains-north/images/sioux-falls-sd-city/attr1-4.jpg"],"price":"Free (est.)"},{"description":"A 45-acre zoo and aquarium with 1,000+ animals, from Amur tigers to stingrays you can touch. The walk-through butterfly house and the aquarium's shark tank are highlights. The zoo's carousel and train keep little ones happy.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Great%20Plains%20Zoo%20Sioux%20Falls%20SD","name":"Great Plains Zoo","officialUrl":"https://www.greatzoo.org/","photos":["assets/plains-north/images/sioux-falls-sd-city/attr2-1.jpg","assets/plains-north/images/sioux-falls-sd-city/attr2-2.jpg","assets/plains-north/images/sioux-falls-sd-city/attr2-3.jpg","assets/plains-north/images/sioux-falls-sd-city/attr2-4.jpg"],"price":"$15/adult, $9/child (est.)"},{"description":"Downtown's arts and science center in a former Washington High School, with a hands-on science museum, concert hall, and art galleries. The Kirby Science Discovery Center's interactive exhibits are perfect for curious kids. Great rainy-day anchor.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Washington%20Pavilion%20Sioux%20Falls%20SD","name":"Washington Pavilion","officialUrl":"https://www.washingtonpavilion.org/","photos":["assets/plains-north/images/sioux-falls-sd-city/attr3-1.jpg","assets/plains-north/images/sioux-falls-sd-city/attr3-2.jpg","assets/plains-north/images/sioux-falls-sd-city/attr3-3.jpg","assets/plains-north/images/sioux-falls-sd-city/attr3-4.jpg"],"price":"$13/adult, $9/child (est.)"},{"description":"A tropical paradise inside the Sertoma Butterfly House, with hundreds of free-flying butterflies from around the world. The adjacent aquarium features sharks, stingrays, and a touch pool. Located at Sertoma Park, west of downtown.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Butterfly%20House%20and%20Aquarium%20Sioux%20Falls%20SD","name":"Butterfly House & Aquarium","officialUrl":"https://www.butterflyhouseaquarium.org/","photos":["assets/plains-north/images/sioux-falls-sd-city/attr4-1.jpg","assets/plains-north/images/sioux-falls-sd-city/attr4-2.jpg","assets/plains-north/images/sioux-falls-sd-city/attr4-3.jpg","assets/plains-north/images/sioux-falls-sd-city/attr4-4.jpg"],"price":"$14/adult, $10/child (est.)"}],"bestSeason":"May–October","budget":650,"budgetNote":"Estimate for 2 adults + 2 kids: attraction tickets, meals, and parking; lodging not included.","days":2,"destination":"Sioux Falls, SD","driveNotes":"Sioux Falls is on I-90/I-29 in southeastern South Dakota, 4 hours from Minneapolis and 5.5 from Omaha. Everything here is within a 15-minute drive. Falls Park has free parking; downtown Phillips Avenue is walkable with metered parking that's free on weekends.","familyFriendly":"Best for ages 3+. Falls Park paths are stroller-friendly; the zoo and butterfly house delight toddlers.","heroPhoto":"assets/plains-north/images/sioux-falls-sd-city/hero.jpg","highlights":["Watch the Big Sioux River crash over pink quartzite at Falls Park","Walk among hundreds of butterflies at the Butterfly House","Touch stingrays at the Great Plains Zoo aquarium","Explore hands-on science at the Washington Pavilion","See the falls lit up at night from the observation tower"],"id":"sioux-falls-sd-city","interests":["family","museums","food","nature"],"itinerary":[{"afternoon":{"cost":"$15/adult, $9/child (est.)","description":"This 45-acre zoo has over 1,000 animals, including tigers, giraffes, and a walk-through Australian exhibit. The aquarium's touch pool lets kids feel stingrays. Plan 3 hours at an easy pace.","stop":"Great Plains Zoo","time":"1:00 PM – 4:00 PM"},"day":1,"evening":{"cost":"Free (est.)","description":"Return to Falls Park after dark to see the waterfalls illuminated — a local tradition. Then dinner downtown on Phillips Avenue, the city's lively restaurant row.","stop":"Falls Park at night & downtown dinner","time":"7:00 PM – 9:00 PM"},"morning":{"cost":"Free (est.)","description":"Start at the city's crown jewel: 123 acres of waterfalls, quartzite cliffs, and the old Queen Bee Mill ruins. Climb the 50-foot observation tower for the best view, and walk the paved loop. Budget 2–3 hours.","stop":"Falls Park","time":"9:00 AM – 12:00 PM"},"title":"Falls & Animals"},{"afternoon":{"cost":"$14/adult, $10/child (est.)","description":"Hundreds of tropical butterflies fly free in the warm conservatory — kids are enchanted. The connected aquarium has sharks, jellyfish, and a touch pool. A perfect final stop before the drive home.","stop":"Butterfly House & Aquarium","time":"1:30 PM – 3:30 PM"},"day":2,"evening":{"cost":"Gas only (est.)","description":"An afternoon departure puts you in Minneapolis by evening or Omaha by night. Sioux Falls is an easy on/off from I-90 and I-29.","stop":"Drive home","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"$13/adult, $9/child (est.)","description":"Downtown's arts and science hub, with the hands-on Kirby Science Discovery Center that kids adore. Interactive exhibits on physics, the body, and dinosaurs fill a happy morning.","stop":"Washington Pavilion","time":"10:00 AM – 12:30 PM"},"title":"Science & Butterflies"}],"lat":43.54576,"lng":-96.73131,"overview":"South Dakota's largest city is an easy, affordable family weekend built around a gorgeous waterfall park in the middle of town. Add a well-loved zoo, a butterfly conservatory, and a hands-on science center, and two days fly by. Downtown's restaurant row keeps everyone fed and happy. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Washington Pavilion (science museum + art)","Butterfly House & Aquarium","Great Plains Zoo (indoor aquarium + primate building)"],"region":"Southeast SD","related":["fargo-nd-city","deadwood-sd-wildwest","black-hills-sd-mountains"],"restaurants":[{"detail":"Downtown Sioux Falls institution with great burgers and a kids' menu.","name":"Crawford's Bar & Grill","price":"$$"},{"detail":"Mediterranean favorites in a warm, lively downtown setting.","name":"Sanaa's Gourmet Mediterranean","price":"$$"},{"detail":"Beloved local bakery-cafe famous for chislic and pies.","name":"Queen City Bakery","price":"$"}],"state":"SD","stateName":"South Dakota","tagline":"A waterfall in the middle of the city, plus a great zoo and butterflies galore.","title":"Sioux Falls, SD: Two-Day City Escape","tripType":"city escape","imageAsset":"assets/plains-north/images/sioux-falls-sd-city/hero.jpg"},{"attractions":[{"description":"The entire town is a National Historic Landmark — the gold-rush main street where Wild Bill Hickok was shot in 1876. Walk the wooden boardwalks, watch the daily shootout reenactments, and peek into saloons that feel straight out of a western. Free to wander.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Historic%20Main%20Street%20Deadwood%20SD","name":"Historic Deadwood Main Street","officialUrl":"https://www.deadwood.com/","photos":["assets/plains-north/images/deadwood-sd-wildwest/attr1-1.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr1-2.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr1-3.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr1-4.jpg"],"price":"Free to explore (est.)"},{"description":"The hilltop cemetery where Wild Bill Hickok and Calamity Jane rest side by side. The short uphill walk offers sweeping views of the gulch town below. Kids are fascinated by the outlaw lore — read the headstones together.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mount%20Moriah%20Cemetery%20Deadwood%20SD","name":"Mount Moriah Cemetery","officialUrl":"https://www.deadwood.com/","photos":["assets/plains-north/images/deadwood-sd-wildwest/attr2-1.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr2-2.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr2-3.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr2-4.jpg"],"price":"$3/person (est.)"},{"description":"Kevin Costner's tribute to the buffalo features a stunning bronze sculpture of 14 bison pursued by Lakota hunters. The interactive center tells the story of the great herds with art and film. A beautiful, moving stop just outside town.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tatanka%20Story%20of%20the%20Bison%20Deadwood%20SD","name":"Tatanka: Story of the Bison","officialUrl":"https://www.storyofthebison.com/","photos":["assets/plains-north/images/deadwood-sd-wildwest/attr3-1.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr3-2.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr3-3.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr3-4.jpg"],"price":"$14/adult, kids 6–17 $8 (est.)"},{"description":"Housed in an 1892 Victorian home, this museum covers Deadwood's gold-rush history with the actual chair Wild Bill was sitting in when he was killed. The basement holds the town's archives and some delightfully odd artifacts. Kids love the outlaw stories.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Adams%20Museum%20Deadwood%20SD","name":"Adams Museum","officialUrl":"https://www.deadwoodhistory.com/","photos":["assets/plains-north/images/deadwood-sd-wildwest/attr4-1.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr4-2.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr4-3.jpg","assets/plains-north/images/deadwood-sd-wildwest/attr4-4.jpg"],"price":"$5/adult, kids free (est.)"}],"bestSeason":"June–September","budget":850,"budgetNote":"Estimate for 2 adults + 2 kids: attraction tickets, meals, and parking; lodging not included.","days":3,"destination":"Deadwood, SD","driveNotes":"Deadwood is in the northern Black Hills, about 45 minutes from Rapid City via US-385. The town sits in a steep gulch — parking garages are the norm, and the trolley helps with the hills. Combine easily with the Black Hills or Devils Tower, each about an hour away.","familyFriendly":"Best for ages 6+. The outlaw history captivates school-age kids; the hills mean lots of walking — wear good shoes.","heroPhoto":"assets/plains-north/images/deadwood-sd-wildwest/hero.jpg","highlights":["Watch a wild west shootout on historic Main Street","Visit Wild Bill and Calamity Jane's graves on Mount Moriah","See the breathtaking bison sculpture at Tatanka","Tour the Adams Museum's gold-rush artifacts","Ride the 1880 Train from nearby Hill City"],"id":"deadwood-sd-wildwest","interests":["family","historical-sites","outdoors","scenic"],"itinerary":[{"afternoon":{"cost":"$5/adult, kids free (est.)","description":"This 1892 mansion-turned-museum holds Deadwood's best artifacts, including the chair Wild Bill Hickok was sitting in when shot. The gold-rush exhibits and odd curiosities keep kids engaged.","stop":"Adams Museum","time":"1:30 PM – 3:30 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner in a historic saloon or steakhouse, then an evening stroll as the gulch lights come on. Summer evenings often feature live music on Main Street.","stop":"Dinner on Main Street","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Free (est.)","description":"Stroll the National Historic Landmark main street — wooden boardwalks, 1870s facades, and daily shootout reenactments in summer. Pop into the saloons (kids welcome by day) and the brothel-turned-museum if the kids are older.","stop":"Historic Deadwood Main Street","time":"9:30 AM – 12:30 PM"},"title":"Gold Rush Town"},{"afternoon":{"cost":"$14/adult, kids 6–17 $8 (est.)","description":"Just outside town, Kevin Costner's center features a breathtaking bronze of bison being pursued by Lakota hunters. The interactive exhibits on the great herds are moving and beautifully done.","stop":"Tatanka: Story of the Bison","time":"2:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free to browse (est.)","description":"Browse the rock shops and fudge stores, then catch the evening ghost tour if the kids are brave enough. Deadwood's haunted history is half the fun.","stop":"Evening in Deadwood","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$3/person (est.)","description":"Walk (or take the shuttle) up to the famous boot hill cemetery. Wild Bill Hickok and Calamity Jane lie side by side with a view over the whole gulch. Read the headstone stories together.","stop":"Mount Moriah Cemetery","time":"9:30 AM – 11:30 AM"},"title":"Outlaws & Bison"},{"afternoon":{"cost":"$60–$90 for the family (est.)","description":"Drive 20 minutes to Hill City for the 1880 Train — a historic steam ride through old mining country. Or visit the Days of '76 Museum for rodeo and pioneer history. A fitting final adventure.","stop":"1880 Train or Days of '76 Museum","time":"1:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"Gas only (est.)","description":"Deadwood is 45 minutes from Rapid City and I-90. An afternoon departure gets you home or onward with ease.","stop":"Drive home","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free (est.)","description":"A relaxed morning: pancakes in a historic cafe and one last boardwalk stroll. Pick up cowboy hats for the kids — they'll wear them all the way home.","stop":"Farewell breakfast","time":"9:00 AM – 11:00 AM"},"title":"Farewell to the Gulch"}],"lat":44.37653,"lng":-103.72963,"overview":"Deadwood is the real Old West — a gold-rush town in a steep Black Hills gulch where Wild Bill Hickok met his end in 1876. The whole main street is a National Historic Landmark, with shootout reenactments, saloons, and museums that make history feel alive. It's an easy add-on to any Black Hills trip. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Adams Museum","Days of '76 Museum","Deadwood History's Homestake Adams Research Center (seasonal exhibits)"],"region":"Northern Black Hills","related":["black-hills-sd-mountains","custer-sd-wildlife","devils-tower-wy-monument"],"restaurants":[{"detail":"Historic steakhouse in an 1876 building with a big family menu.","name":"Legends Steakhouse","price":"$$"},{"detail":"Casual spot famous for burgers and old-west atmosphere.","name":"Deadwood Social Club","price":"$$"},{"detail":"Old-fashioned soda fountain with burgers and shakes on Main Street.","name":"Jacobs Brewhouse & Grocer","price":"$"}],"state":"SD","stateName":"South Dakota","tagline":"The real Old West — gold-rush streets, outlaw graves, and daily shootouts.","title":"Deadwood, SD: Three-Day Wild West Adventure","tripType":"wild west adventure","imageAsset":"assets/plains-north/images/deadwood-sd-wildwest/hero.jpg"},{"attractions":[{"description":"One of America's great state parks: 71,000 acres of pine forest, granite spires, and open prairie. The 18-mile Wildlife Loop Road almost guarantees bison, pronghorn, and the famous begging burros. The park's lodges and lakes make it a destination in itself.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Custer%20State%20Park%20Custer%20SD","name":"Custer State Park","officialUrl":"https://gfp.sd.gov/parks/detail/custer-state-park/","photos":["assets/plains-north/images/custer-sd-wildlife/attr1-1.jpg","assets/plains-north/images/custer-sd-wildlife/attr1-2.jpg","assets/plains-north/images/custer-sd-wildlife/attr1-3.jpg","assets/plains-north/images/custer-sd-wildlife/attr1-4.jpg"],"price":"$20/vehicle, 7-day pass (est.)"},{"description":"A jewel-like mountain lake ringed by granite formations, with a sandy swimming beach, paddleboat rentals, and easy trails. The Sunday Gulch Trail thrills adventurous hikers; families love the calm water and picnic areas. Arrive early on summer weekends.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sylvan%20Lake%20Custer%20SD","name":"Sylvan Lake","officialUrl":"https://gfp.sd.gov/parks/detail/custer-state-park/","photos":["assets/plains-north/images/custer-sd-wildlife/attr2-1.jpg","assets/plains-north/images/custer-sd-wildlife/attr2-2.jpg","assets/plains-north/images/custer-sd-wildlife/attr2-3.jpg","assets/plains-north/images/custer-sd-wildlife/attr2-4.jpg"],"price":"Included with park pass (est.)"},{"description":"A spectacular 14-mile drive past granite needles and through impossibly narrow tunnels. The Needles Eye formation and Cathedral Spires pullouts are must-stops. Drive slowly — the road demands it, and the views reward it.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Needles%20Highway%20Custer%20SD","name":"Needles Highway","officialUrl":"https://gfp.sd.gov/parks/detail/custer-state-park/","photos":["assets/plains-north/images/custer-sd-wildlife/attr3-1.jpg","assets/plains-north/images/custer-sd-wildlife/attr3-2.jpg","assets/plains-north/images/custer-sd-wildlife/attr3-3.jpg","assets/plains-north/images/custer-sd-wildlife/attr3-4.jpg"],"price":"Included with park pass (est.)"},{"description":"The largest of the park's lakes, with a historic 1920s lodge, swimming beach, and boat rentals. The easy Legion Lake Trail loops through pine forest, and evening ranger programs run in summer. A great base for park days.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Legion%20Lake%20Custer%20SD","name":"Legion Lake","officialUrl":"https://gfp.sd.gov/parks/detail/custer-state-park/","photos":["assets/plains-north/images/custer-sd-wildlife/attr4-1.jpg","assets/plains-north/images/custer-sd-wildlife/attr4-2.jpg","assets/plains-north/images/custer-sd-wildlife/attr4-3.jpg","assets/plains-north/images/custer-sd-wildlife/attr4-4.jpg"],"price":"Included with park pass (est.)"}],"bestSeason":"May–October","budget":900,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, meals, and gas; lodging not included.","days":3,"destination":"Custer, SD","driveNotes":"Custer town sits just outside the state park's west entrance on US-16, about 40 minutes from Rapid City. The Wildlife Loop is best at dawn or dusk; Needles Highway is narrow with one-lane tunnels — no trailers. Fill up in Custer town; there's no gas inside the park.","familyFriendly":"Best for ages 4+. The Wildlife Loop is perfect for car-bound toddlers; Sylvan Lake's beach suits all ages.","heroPhoto":"assets/plains-north/images/custer-sd-wildlife/hero.jpg","highlights":["Drive the Wildlife Loop past bison herds and begging burros","Swim and paddle at crystal-clear Sylvan Lake","Thread the Needles Highway's granite tunnels","Hike the easy trails around Legion Lake","Join a summer ranger program under the stars"],"id":"custer-sd-wildlife","interests":["family","outdoors","nature","scenic"],"itinerary":[{"afternoon":{"cost":"Included with park pass (est.)","description":"Head to Sylvan Lake for swimming, paddleboats, and the easy shoreline trail. The granite formations rising from the water make it one of the prettiest lakes in America. Arrive by mid-afternoon for the best beach spots.","stop":"Sylvan Lake","time":"1:30 PM – 4:30 PM"},"day":1,"evening":{"cost":"Free (est.)","description":"Dinner back in the town of Custer, then an early night. The town is small, friendly, and full of family restaurants.","stop":"Dinner in Custer","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$20/vehicle, 7-day pass (est.)","description":"Enter the park and drive the 18-mile Wildlife Loop. Bison herds, pronghorn, and the park's famous begging burros are most active in the morning. Bring carrots for the burros (it's allowed!) and binoculars for the kids.","stop":"Wildlife Loop Road","time":"8:30 AM – 11:30 AM"},"title":"Wildlife & Water"},{"afternoon":{"cost":"Included with park pass (est.)","description":"Swim, rent a paddleboat, or walk the easy Legion Lake Trail through the pines. The historic lodge's porch is a lovely spot for ice cream. Evening ranger talks happen here in summer.","stop":"Legion Lake","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"Free with park pass (est.)","description":"Join a ranger-led evening program — campfire talks on bison, stars, and park history run through summer. Check the park schedule at the visitor center.","stop":"Ranger program","time":"7:00 PM – 8:30 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Drive the 14-mile Needles Highway through granite spires and one-lane tunnels. Stop at the Needles Eye and Cathedral Spires overlooks. Allow 2 hours with photo stops — the road is slow but stunning.","stop":"Needles Highway","time":"9:00 AM – 11:30 AM"},"title":"Needles & Lakes"},{"afternoon":{"cost":"Gas only (est.)","description":"A relaxed final afternoon: one more Wildlife Loop drive for any animals you missed, then head out. The park's west entrance puts you on the road to Wyoming or back to Rapid City.","stop":"Farewell wildlife drive","time":"1:00 PM – 3:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Custer is 40 minutes from Rapid City and an hour from Devils Tower. Depart mid-afternoon for an easy evening drive.","stop":"Drive home","time":"3:30 PM – 5:30 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Dawn is the best wildlife hour — return to the Wildlife Loop for bison in the morning light. Then a hearty breakfast in town before checkout.","stop":"Sunrise wildlife drive & breakfast","time":"7:00 AM – 10:00 AM"},"title":"Sunrise Sendoff"}],"lat":43.76961,"lng":-103.60206,"overview":"Custer State Park is the Black Hills' wild heart — 71,000 acres where bison herds cross the road and granite spires pierce the sky. The town of Custer makes a perfect base for wildlife drives, lake days at Sylvan Lake, and the thrilling Needles Highway. Three days here feels like a true wilderness escape with a comfortable bed nearby. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Custer County 1881 Courthouse Museum","Four Mile Old West Town (covered buildings)","Crazy Horse Memorial's museums (30 min away)"],"region":"Southern Black Hills","related":["black-hills-sd-mountains","badlands-sd-park","deadwood-sd-wildwest"],"restaurants":[{"detail":"Old-west steakhouse with a huge family menu in downtown Custer.","name":"Black Hills Burger and Bun Co","price":"$$"},{"detail":"Beloved local spot for burgers and shakes.","name":"Baker's Bakery & Cafe","price":"$"},{"detail":"Chef-driven Scandinavian tasting room — a special-occasion splurge.","name":"Skogen Kitchen","price":"$$$"}],"state":"SD","stateName":"South Dakota","tagline":"Bison herds, granite spires, and the prettiest mountain lakes in the Black Hills.","title":"Custer, SD: Three-Day Wildlife & Lakes Retreat","tripType":"wildlife retreat","imageAsset":"assets/plains-north/images/custer-sd-wildlife/hero.jpg"},{"attractions":[{"description":"The 50-mile engineering marvel crossing the Continental Divide at Logan Pass (6,646 ft). Waterfalls, wildflower meadows, and mountain goats line the route; vehicle reservations are required in summer. Drive it slowly — every mile has a pullout worth stopping for.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Going-to-the-Sun%20Road%20Glacier%20National%20Park%20MT","name":"Going-to-the-Sun Road","officialUrl":"https://www.nps.gov/glac/","photos":["assets/plains-north/images/glacier-mt-park/attr1-1.jpg","assets/plains-north/images/glacier-mt-park/attr1-2.jpg","assets/plains-north/images/glacier-mt-park/attr1-3.jpg","assets/plains-north/images/glacier-mt-park/attr1-4.jpg"],"price":"$35/vehicle, 7-day pass; reservation may be required (est.)"},{"description":"The park's largest lake, with famously clear water and colorful pebbles along the shore. Rent a kayak, take a historic boat tour, or just walk the Trail of the Cedars. The 1915 Lake McDonald Lodge is worth a visit for its grand lobby.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake%20McDonald%20Glacier%20National%20Park%20MT","name":"Lake McDonald","officialUrl":"https://www.nps.gov/glac/","photos":["assets/plains-north/images/glacier-mt-park/attr2-1.jpg","assets/plains-north/images/glacier-mt-park/attr2-2.jpg","assets/plains-north/images/glacier-mt-park/attr2-3.jpg","assets/plains-north/images/glacier-mt-park/attr2-4.jpg"],"price":"Included with park pass (est.)"},{"description":"The park's wildlife capital, where grizzlies, moose, and mountain goats are regularly spotted. Swiftcurrent Lake offers easy boat tours and the short trail to Fishercap Lake for moose at dawn. The historic Many Glacier Hotel anchors the valley.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Many%20Glacier%20Glacier%20National%20Park%20MT","name":"Many Glacier","officialUrl":"https://www.nps.gov/glac/","photos":["assets/plains-north/images/glacier-mt-park/attr3-1.jpg","assets/plains-north/images/glacier-mt-park/attr3-2.jpg","assets/plains-north/images/glacier-mt-park/attr3-3.jpg","assets/plains-north/images/glacier-mt-park/attr3-4.jpg"],"price":"Included with park pass (est.)"},{"description":"The high point of the Sun Road, where boardwalk trails cross alpine meadows full of wildflowers. The Hidden Lake Overlook trail is an easy family hike with mountain goat sightings almost guaranteed. The visitor center has exhibits kids love.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Logan%20Pass%20Glacier%20National%20Park%20MT","name":"Logan Pass","officialUrl":"https://www.nps.gov/glac/","photos":["assets/plains-north/images/glacier-mt-park/attr4-1.jpg","assets/plains-north/images/glacier-mt-park/attr4-2.jpg","assets/plains-north/images/glacier-mt-park/attr4-3.jpg","assets/plains-north/images/glacier-mt-park/attr4-4.jpg"],"price":"Included with park pass (est.)"}],"bestSeason":"July–September","budget":1100,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, boat tour, meals, and gas; lodging not included.","days":4,"destination":"Glacier, MT","driveNotes":"Base on the west side (Whitefish/Kalispell) or east side (St. Mary) — crossing the park takes 2+ hours on the Sun Road. Vehicle reservations for the Sun Road and North Fork are required in summer; book on recreation.gov the moment they release. Gas up outside the park — there are no stations inside.","familyFriendly":"Best for ages 6+. Trails are stunning but exposed; carry bear spray and make noise on hikes. The Sun Road thrills kids but has sheer drops — keep little ones buckled.","heroPhoto":"assets/plains-north/images/glacier-mt-park/hero.jpg","highlights":["Drive the Going-to-the-Sun Road over Logan Pass","Spot mountain goats on the Hidden Lake Overlook trail","Cruise crystal-clear Lake McDonald","Watch for grizzlies and moose in Many Glacier","Walk the Trail of the Cedars' boardwalks"],"id":"glacier-mt-park","interests":["family","outdoors","nature","scenic"],"itinerary":[{"afternoon":{"cost":"Included with park pass (est.)","description":"Continue up the Sun Road, stopping at waterfalls and pullouts. The Weeping Wall often sprays the road — kids love it. Reach Logan Pass by late afternoon for the boardwalk trails and the visitor center.","stop":"Going-to-the-Sun Road, upper half & Logan Pass","time":"1:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Drive back down to the west side for dinner. Summer sunsets are late in Montana — enjoy the long evening at your lodge.","stop":"Dinner on the west side","time":"6:30 PM – 8:30 PM"},"morning":{"cost":"$35/vehicle, 7-day pass (est.)","description":"Enter at West Glacier and drive the lower Sun Road. Stop at Lake McDonald for the Trail of the Cedars — an easy, stroller-friendly boardwalk through old-growth forest. Picnic by the lake.","stop":"Going-to-the-Sun Road, lower half & Lake McDonald","time":"9:00 AM – 12:30 PM"},"title":"The Sun Road"},{"afternoon":{"cost":"Included with park pass (est.)","description":"Hike the easy 1.5-mile Hidden Lake Overlook trail from Logan Pass — mountain goats graze right by the boardwalk in summer. Wildflowers carpet the meadows in July. The visitor center's exhibits entertain while you rest.","stop":"Logan Pass & Hidden Lake Overlook","time":"1:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"$30–$50 for boat tour (est.)","description":"Return to the west side for an evening stroll along Lake McDonald. The historic boat tours at golden hour are magical if you book ahead.","stop":"Evening at Lake McDonald","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Head back up the Sun Road early for a full Logan Pass morning. The Highline Trail's first mile is gentle and spectacular — turn around whenever the kids are ready.","stop":"Highline Trail (first section)","time":"8:30 AM – 12:00 PM"},"title":"Alpine Meadows"},{"afternoon":{"cost":"$25–$40 for boat tour (est.)","description":"Take the historic boat tour across Swiftcurrent Lake, or hike the easy trail to Fishercap Lake where moose feed at the shore. The valley's wildlife viewing is the park's best.","stop":"Many Glacier boat tour & trails","time":"1:00 PM – 4:30 PM"},"day":3,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Dinner at the historic Many Glacier Hotel's dining room, with its massive fireplace and Swiss-chalet feel. Then the long, scenic drive back around the park's south side.","stop":"Many Glacier Hotel dinner","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"Included with park pass (est.)","description":"The big day: drive around the park to the east side and into the Many Glacier valley. It's a long drive (2+ hours) but spectacular. Watch for bears along the road — rangers post recent sightings.","stop":"Drive to Many Glacier","time":"8:00 AM – 11:30 AM"},"title":"Many Glacier Wildlife"},{"afternoon":{"cost":"Gas only (est.)","description":"Kalispell is 30 minutes from West Glacier with an airport and all services. Depart after lunch for an easy travel day.","stop":"Drive home","time":"1:00 PM – 3:00 PM"},"day":4,"evening":{"cost":"Free (est.)","description":"Most families fly out of Kalispell or drive south toward Yellowstone. Either way, leave with full memory cards and tired, happy kids.","stop":"Farewell","time":"3:00 PM – 5:00 PM"},"morning":{"cost":"Free (est.)","description":"A slow final morning: breakfast in Whitefish or West Glacier, a last walk by the water, and souvenir shopping. The park's west entrance makes a convenient farewell stop.","stop":"Whitefish or West Glacier morning","time":"9:00 AM – 12:00 PM"},"title":"Farewell"}],"lat":48.69703,"lng":-113.71985,"overview":"Glacier is the Crown of the Continent — jagged peaks, turquoise lakes, and the legendary Going-to-the-Sun Road crossing the Continental Divide. Families come for the jaw-dropping drives, easy alpine hikes, and wildlife from mountain goats to grizzlies. Summer reservations are essential, but the payoff is unforgettable. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Apgar Visitor Center (films + exhibits)","Glacier National Park's Lake McDonald Lodge (lobby + ranger talks)","Hockaday Museum of Art (Kalispell)"],"region":"Northwest MT","related":["whitefish-mt-alpine","yellowstone-wy-park","gardiner-mt-yellowstone"],"restaurants":[{"detail":"Classic Montana steakhouse in Babb, on the park's east side.","name":"Cattle Baron Supper Club","price":"$$"},{"detail":"Family-friendly spot in Columbia Falls with great burgers.","name":"Back Room Restaurant","price":"$$"},{"detail":"Casual pizza and pub fare in Whitefish, perfect after a park day.","name":"Blackstar Brewing","price":"$"}],"state":"MT","stateName":"Montana","tagline":"The Crown of the Continent — alpine roads, turquoise lakes, and mountain goats.","title":"Glacier, MT: Four-Day National Park Adventure","tripType":"national park adventure","imageAsset":"assets/plains-north/images/glacier-mt-park/hero.jpg"},{"attractions":[{"description":"Yellowstone's quieter northern hub, where steaming travertine terraces cascade down the hillside. Boardwalks wind through the colorful formations, and elk graze the lawns in town. The Albright Visitor Center's exhibits are excellent for kids.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mammoth%20Hot%20Springs%20Yellowstone%20National%20Park","name":"Mammoth Hot Springs","officialUrl":"https://www.nps.gov/yell/","photos":["assets/plains-north/images/gardiner-mt-yellowstone/attr1-1.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr1-2.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr1-3.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr1-4.jpg"],"price":"$35/vehicle, 7-day pass (est.)"},{"description":"Yellowstone's best wildlife-watching valley, where wolf packs, grizzlies, bison herds, and elk are regularly seen. Dawn and dusk are prime time — bring binoculars and a spotting scope if you have one. Rangers often set up scopes at pullouts.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lamar%20Valley%20Yellowstone%20National%20Park","name":"Lamar Valley","officialUrl":"https://www.nps.gov/yell/","photos":["assets/plains-north/images/gardiner-mt-yellowstone/attr2-1.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr2-2.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr2-3.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr2-4.jpg"],"price":"Included with park pass (est.)"},{"description":"The iconic 1903 stone arch marking Yellowstone's original north entrance. Kids love walking through it for the classic photo. The nearby town of Gardiner has restaurants and the Yellowstone Heritage and Research Center nearby.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Roosevelt%20Arch%20Gardiner%20MT","name":"Roosevelt Arch","officialUrl":"https://www.nps.gov/yell/","photos":["assets/plains-north/images/gardiner-mt-yellowstone/attr3-1.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr3-2.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr3-3.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr3-4.jpg"],"price":"Free (est.)"},{"description":"Natural hot springs pools on the Yellowstone River just north of Gardiner, with several soaking pools of varying temperatures. The setting — river canyon, mountain views — is gorgeous. Check current access rules; capacity is limited and it closes periodically.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Yellowstone%20Hot%20Springs%20Gardiner%20MT","name":"Yellowstone Hot Springs","officialUrl":"https://www.yellowstonehotsprings.com/","photos":["assets/plains-north/images/gardiner-mt-yellowstone/attr4-1.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr4-2.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr4-3.jpg","assets/plains-north/images/gardiner-mt-yellowstone/attr4-4.jpg"],"price":"$18/adult, $12/child (est.)"}],"bestSeason":"June–September","budget":1000,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, hot springs, meals, and gas; lodging not included.","days":3,"destination":"Gardiner, MT","driveNotes":"Gardiner is at Yellowstone's north entrance, 80 minutes from Bozeman via US-89 through Paradise Valley. The north entrance is open year-round, unlike most park roads. Book lodging in Gardiner early — it's a small town and summer fills up. Cell service dies inside the park; download offline maps.","familyFriendly":"Best for ages 5+. Lamar Valley's dawn wildlife drives thrill kids; boardwalks at Mammoth are stroller-friendly.","heroPhoto":"assets/plains-north/images/gardiner-mt-yellowstone/hero.jpg","highlights":["Walk the steaming terraces of Mammoth Hot Springs","Spot wolves and bears in Lamar Valley at dawn","Walk through the historic Roosevelt Arch","Soak in Yellowstone Hot Springs under the stars","Drive the scenic Paradise Valley from Bozeman"],"id":"gardiner-mt-yellowstone","interests":["family","nature","outdoors","scenic","historical-sites"],"itinerary":[{"afternoon":{"cost":"Included with park pass (est.)","description":"Walk the boardwalks through the colorful travertine terraces — kids are fascinated by the steaming, otherworldly formations. The Albright Visitor Center's wildlife exhibits are a great cool-down stop.","stop":"Mammoth Hot Springs terraces","time":"1:30 PM – 4:00 PM"},"day":1,"evening":{"cost":"$18/adult, $12/child (est.)","description":"End the day soaking in natural hot springs pools along the Yellowstone River. The family-friendly pools and mountain views make a perfect first-night wind-down.","stop":"Yellowstone Hot Springs","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Walk through the 1903 Roosevelt Arch for the classic Yellowstone photo, then enter the park. Drive up to Mammoth Hot Springs (5 miles) as elk often graze the historic lawns.","stop":"Roosevelt Arch & park entry","time":"9:00 AM – 12:00 PM"},"title":"Hot Springs & History"},{"afternoon":{"cost":"Included with park pass (est.)","description":"Continue east to Tower Fall and the scenic Tower-Roosevelt area. The short trail to the falls overlook is easy, and the general store makes a fun stop for huckleberry ice cream.","stop":"Tower Fall & Tower-Roosevelt","time":"2:00 PM – 5:00 PM"},"day":2,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Back in Gardiner for dinner — the town's restaurants are casual and welcoming after a long park day. An early night sets up tomorrow's dawn patrol.","stop":"Dinner in Gardiner","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Rise before dawn and drive into Lamar Valley — America's Serengeti. Wolf packs, grizzlies, and bison herds are most active at first light. Rangers often have spotting scopes set up at pullouts. Bring breakfast to eat in the car.","stop":"Lamar Valley wildlife watching","time":"6:00 AM – 11:00 AM"},"title":"Lamar Valley Wildlife"},{"afternoon":{"cost":"Gas only (est.)","description":"The drive south through Paradise Valley to Bozeman is gorgeous — follow the Yellowstone River past Absaroka peaks. Stop in Livingston for lunch and its railroad museum if time allows.","stop":"Drive to Bozeman via Paradise Valley","time":"1:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Bozeman has an airport and full services — a convenient endpoint. Or continue the adventure: Yellowstone's geyser basins are a day trip south.","stop":"Farewell","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Included with park pass (est.)","description":"One last morning in the park: revisit Mammoth's terraces in the early light or try the easy Beaver Ponds loop trail. Check out of your Gardiner lodging by late morning.","stop":"Final park morning","time":"9:00 AM – 12:00 PM"},"title":"Farewell Drive"}],"lat":45.03327,"lng":-110.70579,"overview":"Gardiner is the classic gateway to Yellowstone's wild northern range — Mammoth's steaming terraces, wolf country in Lamar Valley, and the historic Roosevelt Arch. Staying here puts you inside the action without the crowds of the park's busier south side. Three days covers the highlights with real wildlife moments the kids will never forget. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Albright Visitor Center (Mammoth)","Yellowstone Heritage and Research Center (tours, seasonal)","Gardiner's Yellowstone Gateway Museum"],"region":"Yellowstone Country","related":["yellowstone-wy-park","bozeman-mt-mountain","glacier-mt-park"],"restaurants":[{"detail":"Classic Montana steakhouse in downtown Gardiner.","name":"The Iron Horse Bar & Grill","price":"$$"},{"detail":"Family-friendly spot with great burgers and local brews.","name":"Wonderland Cafe & Lodge","price":"$$"},{"detail":"Casual cafe with hearty breakfasts before park days.","name":"Yellowstone Grill","price":"$"}],"state":"MT","stateName":"Montana","tagline":"Yellowstone's wild north — steaming terraces, wolf country, and the historic arch.","title":"Gardiner, MT: Three-Day Yellowstone Gateway","tripType":"yellowstone gateway","imageAsset":"assets/plains-north/images/gardiner-mt-yellowstone/hero.jpg"},{"attractions":[{"description":"One of America's great dinosaur museums, home to the world's largest Tyrannosaurus skull and a stunning paleontology hall. The planetarium and living-history farm round out a full day. Kids can watch real fossil prep in the lab.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Museum%20of%20the%20Rockies%20Bozeman%20MT","name":"Museum of the Rockies","officialUrl":"https://www.museumoftherockies.org/","photos":["assets/plains-north/images/bozeman-mt-mountain/attr1-1.jpg","assets/plains-north/images/bozeman-mt-mountain/attr1-2.jpg","assets/plains-north/images/bozeman-mt-mountain/attr1-3.jpg","assets/plains-north/images/bozeman-mt-mountain/attr1-4.jpg"],"price":"$18/adult, $11/child (est.)"},{"description":"A sanctuary for rescued grizzly bears that can't be released to the wild, with viewing platforms and naturalist talks. Seeing a grizzly up close (safely) is thrilling and educational. The enclosures are large and the bears are active.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Montana%20Grizzly%20Encounter%20Bozeman%20MT","name":"Montana Grizzly Encounter","officialUrl":"https://www.grizzlyencounter.org/","photos":["assets/plains-north/images/bozeman-mt-mountain/attr2-1.jpg","assets/plains-north/images/bozeman-mt-mountain/attr2-2.jpg","assets/plains-north/images/bozeman-mt-mountain/attr2-3.jpg","assets/plains-north/images/bozeman-mt-mountain/attr2-4.jpg"],"price":"$10/adult, $5/child (est.)"},{"description":"A mountain canyon 20 minutes south of town with waterfalls, a reservoir, and easy trails. The short hike to Palisade Falls (in the nearby Gallatin range) or the Hyalite Creek trail suits families. Swimming holes cool everyone off in summer.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hyalite%20Canyon%20Bozeman%20MT","name":"Hyalite Canyon","officialUrl":"https://www.fs.usda.gov/recarea/custergallatin/recarea/?recid=53532","photos":["assets/plains-north/images/bozeman-mt-mountain/attr3-1.jpg","assets/plains-north/images/bozeman-mt-mountain/attr3-2.jpg","assets/plains-north/images/bozeman-mt-mountain/attr3-3.jpg","assets/plains-north/images/bozeman-mt-mountain/attr3-4.jpg"],"price":"Free (est.)"},{"description":"Bozeman's vibrant main street, lined with historic buildings, bookstores, outdoor shops, and family restaurants. The summer farmers' market and free music events give it a festive feel. A great evening stroll after museum days.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Downtown%20Bozeman%20MT","name":"Downtown Bozeman","officialUrl":"https://www.downtownbozeman.org/","photos":["assets/plains-north/images/bozeman-mt-mountain/attr4-1.jpg","assets/plains-north/images/bozeman-mt-mountain/attr4-2.jpg","assets/plains-north/images/bozeman-mt-mountain/attr4-3.jpg","assets/plains-north/images/bozeman-mt-mountain/attr4-4.jpg"],"price":"Free to explore (est.)"}],"bestSeason":"June–October","budget":900,"budgetNote":"Estimate for 2 adults + 2 kids: museum tickets, meals, and gas; lodging not included.","days":3,"destination":"Bozeman, MT","driveNotes":"Bozeman is on I-90, 90 minutes from Yellowstone's west entrance (West Yellowstone) and 80 minutes from Gardiner. The airport has direct flights from many cities. Downtown parking is easy; trailheads like Hyalite fill up on summer weekends — go early.","familyFriendly":"Best for ages 4+. The dinosaur museum captivates all ages; Hyalite trails are gentle and shaded.","heroPhoto":"assets/plains-north/images/bozeman-mt-mountain/hero.jpg","highlights":["Stand under the world's largest T. rex skull","Meet rescued grizzlies up close","Hike to waterfalls in Hyalite Canyon","Stroll Bozeman's lively downtown","Day-trip to Yellowstone's west side"],"id":"bozeman-mt-mountain","interests":["family","museums","outdoors","nature","food"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Cool off with the living-history farm and the planetarium show (check showtimes). The museum store has excellent dinosaur souvenirs. Plan 3–4 hours total.","stop":"Museum of the Rockies, continued","time":"1:00 PM – 4:00 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner on Main Street, then browse the bookstores and outdoor shops. Summer evenings often bring free concerts to the downtown plaza.","stop":"Downtown Bozeman","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$18/adult, $11/child (est.)","description":"Start at one of America's best dinosaur museums. The Siebel Dinosaur Complex has the world's largest T. rex skull and real Montana fossils. Kids love the hands-on discovery areas and watching fossil prep.","stop":"Museum of the Rockies","time":"9:30 AM – 12:30 PM"},"title":"Dinosaurs & Downtown"},{"afternoon":{"cost":"Free (est.)","description":"Drive 20 minutes south to Hyalite Canyon for an easy family hike — the creekside trail is shaded and gentle, with swimming holes for brave kids. Picnic by Hyalite Reservoir with mountain views.","stop":"Hyalite Canyon","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"Free to browse (est.)","description":"Back in town for dinner and the summer farmers' market if it's a Tuesday. Bozeman's food scene punches above its weight for a mountain town.","stop":"Dinner in Bozeman","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$10/adult, $5/child (est.)","description":"Visit this sanctuary for rescued grizzlies just outside town. Naturalist talks explain bear behavior, and the viewing platforms get you surprisingly close — safely. A thrilling, educational hour.","stop":"Montana Grizzly Encounter","time":"9:30 AM – 11:30 AM"},"title":"Bears & Waterfalls"},{"afternoon":{"cost":"Included with park pass; gas extra (est.)","description":"The west entrance is 90 minutes away — Old Faithful and the geyser basins make a full, unforgettable day. Or stay local: the Gallatin River's pullouts and the Museum of the Rockies' planetarium fill a relaxed day.","stop":"Yellowstone day trip (optional)","time":"12:00 PM – 6:00 PM"},"day":3,"evening":{"cost":"Gas only (est.)","description":"Bozeman's airport makes departures easy. If driving, I-90 east or west is right at your doorstep.","stop":"Drive home","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free (est.)","description":"A slow morning: breakfast downtown, the Saturday farmers' market (seasonal), and one last stroll. Pick up huckleberry treats for the road.","stop":"Farewell Bozeman","time":"9:00 AM – 12:00 PM"},"title":"Farewell"}],"lat":45.67933,"lng":-111.03234,"overview":"Bozeman blends a top-tier dinosaur museum with real Montana outdoors — grizzly encounters, waterfall hikes, and a charming downtown. It's also the handiest base for Yellowstone day trips, sitting between the north and west entrances. Three days here mix learning and adventure at an easy family pace. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Museum of the Rockies (full day)","Bozeman Hot Springs (indoor/outdoor pools)","Downtown Bozeman shops & the Emerson Center for the Arts"],"region":"Gallatin Valley","related":["gardiner-mt-yellowstone","yellowstone-wy-park","missoula-mt-river"],"restaurants":[{"detail":"Montana comfort food in a lively downtown setting.","name":"Montana Ale Works","price":"$$"},{"detail":"Beloved local spot for creative burgers and shakes.","name":"The Pickle Barrel","price":"$"},{"detail":"Farm-to-table favorite with a great kids' menu.","name":"Blackbird Kitchen","price":"$$"}],"state":"MT","stateName":"Montana","tagline":"Dinosaurs, grizzlies, and mountain waterfalls in Montana's coolest college town.","title":"Bozeman, MT: Three-Day Mountain Town Getaway","tripType":"mountain town getaway","imageAsset":"assets/plains-north/images/bozeman-mt-mountain/hero.jpg"},{"attractions":[{"description":"A hand-carved carousel where every horse is a Missoula icon — 38 ponies, two chariots, and a dragon, all carved by local volunteers. The adjacent Dragon Hollow playground is a kid paradise. At $1 a ride, it's the best bargain in Montana.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=A%20Carousel%20for%20Missoula%20Missoula%20MT","name":"A Carousel for Missoula","officialUrl":"https://www.carouselformissoula.com/","photos":["assets/plains-north/images/missoula-mt-river/attr1-1.jpg","assets/plains-north/images/missoula-mt-river/attr1-2.jpg","assets/plains-north/images/missoula-mt-river/attr1-3.jpg","assets/plains-north/images/missoula-mt-river/attr1-4.jpg"],"price":"$1/ride (est.)"},{"description":"A free downtown museum with strong contemporary and historic collections, including one of the country's best holdings of Native American beadwork. The family activity room and rotating exhibits make it a pleasant hour or two. Beautiful historic Carnegie building.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Missoula%20Art%20Museum%20Missoula%20MT","name":"Missoula Art Museum","officialUrl":"https://www.missoulaartmuseum.org/","photos":["assets/plains-north/images/missoula-mt-river/attr2-1.jpg","assets/plains-north/images/missoula-mt-river/attr2-2.jpg","assets/plains-north/images/missoula-mt-river/attr2-3.jpg","assets/plains-north/images/missoula-mt-river/attr2-4.jpg"],"price":"Free (est.)"},{"description":"A vast wilderness minutes from downtown, with the Rattlesnake Creek trailhead leading to gentle creekside paths. Families love the easy walks, birdwatching, and fall colors. The main corridor trail is stroller-friendly for the first mile.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Rattlesnake%20National%20Recreation%20Area%20Missoula%20MT","name":"Rattlesnake National Recreation Area","officialUrl":"https://www.fs.usda.gov/recarea/lolo/recarea/?recid=10378","photos":["assets/plains-north/images/missoula-mt-river/attr3-1.jpg","assets/plains-north/images/missoula-mt-river/attr3-2.jpg","assets/plains-north/images/missoula-mt-river/attr3-3.jpg","assets/plains-north/images/missoula-mt-river/attr3-4.jpg"],"price":"Free (est.)"},{"description":"The Clark Fork River runs right through downtown, with Brennan's Wave — a man-made surf wave — drawing kayakers and spectators. The riverside trails, Caras Park, and summer events make the riverfront the town's living room. Kids love watching the surfers.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Caras%20Park%20Missoula%20MT","name":"Clark Fork River & Caras Park","officialUrl":"https://www.missoulaparks.org/","photos":["assets/plains-north/images/missoula-mt-river/attr4-1.jpg","assets/plains-north/images/missoula-mt-river/attr4-2.jpg","assets/plains-north/images/missoula-mt-river/attr4-3.jpg","assets/plains-north/images/missoula-mt-river/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"June–October","budget":750,"budgetNote":"Estimate for 2 adults + 2 kids: mostly free attractions, meals, and gas; lodging not included.","days":3,"destination":"Missoula, MT","driveNotes":"Missoula is on I-90 in western Montana, 2 hours from Glacier's west side and 3 from Bozeman. The whole itinerary is within 10 minutes of downtown. Parking downtown is easy; the riverfront trails connect most sights without moving the car.","familyFriendly":"Best for ages 3+. The carousel, riverfront, and gentle trails are perfect for toddlers and grandparents alike.","heroPhoto":"assets/plains-north/images/missoula-mt-river/hero.jpg","highlights":["Ride the $1 hand-carved carousel and Dragon Hollow","Watch kayakers surf Brennan's Wave downtown","Walk the creekside trails of the Rattlesnake","Browse free art at the Missoula Art Museum","Picnic in Caras Park by the Clark Fork"],"id":"missoula-mt-river","interests":["family","outdoors","museums","nature"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Walk the paved riverfront trail through Caras Park, where kids can watch kayakers surf Brennan's Wave. The playground and open lawns are perfect for an easy afternoon. Grab huckleberry ice cream from a riverside vendor.","stop":"Clark Fork River & Caras Park","time":"1:30 PM – 4:00 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner downtown — Missoula's food scene is excellent for a small city. An evening stroll along the river caps the day.","stop":"Downtown Missoula dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$1/ride (est.)","description":"Start at this beloved hand-carved carousel — every horse is a Missoula landmark. At $1 a ride, the kids will want several turns. The adjacent Dragon Hollow playground, with its castle and dragon, easily fills the rest of the morning.","stop":"A Carousel for Missoula & Dragon Hollow","time":"10:00 AM – 12:30 PM"},"title":"Carousel & River"},{"afternoon":{"cost":"Free (est.)","description":"This free museum in a historic Carnegie building has excellent Native American beadwork and contemporary exhibits. The hands-on family room keeps kids busy. A calm, cool hour downtown.","stop":"Missoula Art Museum","time":"1:30 PM – 3:00 PM"},"day":2,"evening":{"cost":"Free to browse (est.)","description":"Browse the independent bookstores and shops on Higgins Avenue. Summer brings free concerts to Caras Park — check the schedule.","stop":"Downtown Missoula","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"Free (est.)","description":"Head to the Rattlesnake trailhead for an easy creekside walk. The main trail is gentle and shaded, with great birdwatching. Turn around whenever the kids are ready — even a mile is lovely.","stop":"Rattlesnake National Recreation Area","time":"9:30 AM – 12:00 PM"},"title":"Trails & Art"},{"afternoon":{"cost":"Gas only (est.)","description":"Missoula is 2 hours from Glacier and 3 from Bozeman on I-90. A relaxed afternoon departure works for most routes.","stop":"Drive home","time":"2:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"One last carousel ride for the road — at $1, why not? Then hit I-90 refreshed and happy.","stop":"Farewell","time":"4:00 PM – 5:00 PM"},"morning":{"cost":"Free (est.)","description":"A slow final morning: breakfast at a downtown cafe, one last riverside walk, and browsing the Saturday farmers' market if it's the season. Missoula is easy to love and hard to leave.","stop":"Farewell Missoula","time":"9:00 AM – 12:00 PM"},"title":"Farewell"}],"lat":46.87278,"lng":-113.99625,"overview":"Missoula is Montana's most family-friendly city — a hand-carved $1 carousel, a river with a surf wave running through downtown, and wilderness trails minutes away. It's affordable, walkable, and wonderfully relaxed. Three days here feel like a deep breath, with just enough adventure to keep the kids buzzing. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Missoula Art Museum","A Carousel for Missoula (covered pavilion)","SpectrUM Discovery Area (hands-on science)"],"region":"Western MT","related":["bozeman-mt-mountain","whitefish-mt-alpine","glacier-mt-park"],"restaurants":[{"detail":"Missoula institution for burgers and huckleberry shakes.","name":"The Notorious P.I.G. BBQ","price":"$$"},{"detail":"Wood-fired pizzas in a fun downtown setting.","name":"Biga Pizza","price":"$$"},{"detail":"Classic diner breakfasts the kids will love.","name":"Paul's Pancake Parlor","price":"$"}],"state":"MT","stateName":"Montana","tagline":"A $1 carousel, a surf wave downtown, and wilderness at the edge of town.","title":"Missoula, MT: Three-Day River City Escape","tripType":"river city escape","imageAsset":"assets/plains-north/images/missoula-mt-river/hero.jpg"},{"attractions":[{"description":"A year-round mountain resort with a scenic gondola, alpine slide, zip lines, and mountain biking in summer. The summit views stretch to Glacier National Park. Kids love the alpine slide; the whole family can ride the gondola.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Whitefish%20Mountain%20Resort%20Whitefish%20MT","name":"Whitefish Mountain Resort","officialUrl":"https://skiwhitefish.com/","photos":["assets/plains-north/images/whitefish-mt-alpine/attr1-1.jpg","assets/plains-north/images/whitefish-mt-alpine/attr1-2.jpg","assets/plains-north/images/whitefish-mt-alpine/attr1-3.jpg","assets/plains-north/images/whitefish-mt-alpine/attr1-4.jpg"],"price":"$30–$60/person for summer activities (est.)"},{"description":"A pristine 3,000-acre lake 10 minutes from downtown, with a sandy city beach, boat rentals, and the paved Whitefish Trail for biking. The water is clear and (brace yourself) brisk. Sunset from the city beach is a local ritual.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Whitefish%20Lake%20Whitefish%20MT","name":"Whitefish Lake","officialUrl":"https://www.explorewhitefish.com/","photos":["assets/plains-north/images/whitefish-mt-alpine/attr2-1.jpg","assets/plains-north/images/whitefish-mt-alpine/attr2-2.jpg","assets/plains-north/images/whitefish-mt-alpine/attr2-3.jpg","assets/plains-north/images/whitefish-mt-alpine/attr2-4.jpg"],"price":"Free; rentals extra (est.)"},{"description":"Whitefish's charming main street, with western storefronts, art galleries, and the historic Great Northern Railway depot. The summer farmers' market and free concerts give it a festive feel. A lovely evening stroll after mountain days.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Downtown%20Whitefish%20MT","name":"Downtown Whitefish","officialUrl":"https://www.explorewhitefish.com/","photos":["assets/plains-north/images/whitefish-mt-alpine/attr3-1.jpg","assets/plains-north/images/whitefish-mt-alpine/attr3-2.jpg","assets/plains-north/images/whitefish-mt-alpine/attr3-3.jpg","assets/plains-north/images/whitefish-mt-alpine/attr3-4.jpg"],"price":"Free to explore (est.)"},{"description":"A family-run park with alpine slides, a mountain coaster, zip lines, and an aerial adventure course. It's pure summer fun with Flathead Valley views. A great alternative or add-on to the resort's activities.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Glacier%20Highline%20Whitefish%20MT","name":"Glacier Highline Adventure Park","officialUrl":"https://www.glacierhighline.com/","photos":["assets/plains-north/images/whitefish-mt-alpine/attr4-1.jpg","assets/plains-north/images/whitefish-mt-alpine/attr4-2.jpg","assets/plains-north/images/whitefish-mt-alpine/attr4-3.jpg","assets/plains-north/images/whitefish-mt-alpine/attr4-4.jpg"],"price":"$25–$55/person (est.)"}],"bestSeason":"June–September","budget":950,"budgetNote":"Estimate for 2 adults + 2 kids: resort activities, meals, and gas; lodging not included.","days":3,"destination":"Whitefish, MT","driveNotes":"Whitefish is 30 minutes from Glacier's west entrance and 20 from Kalispell airport. The resort is 10 minutes up Big Mountain Road from downtown. Summer weekends are busy — book the gondola and alpine slide tickets online. Winter visitors get a top-tier ski town instead.","familyFriendly":"Best for ages 5+. The alpine slide has height/age minimums — check before promising the kids.","heroPhoto":"assets/plains-north/images/whitefish-mt-alpine/hero.jpg","highlights":["Ride the gondola to summit views of Glacier Park","Race down the alpine slide","Swim and paddle at Whitefish Lake's city beach","Stroll the charming railway-town downtown","Day-trip into Glacier National Park"],"id":"whitefish-mt-alpine","interests":["family","outdoors","nature","scenic","amusement-parks"],"itinerary":[{"afternoon":{"cost":"$25–$55/person (est.)","description":"Try the adventure park's mountain coaster, zip lines, and alpine slides with valley views. It's an easy, thrilling afternoon the kids will talk about for weeks.","stop":"Glacier Highline Adventure Park","time":"1:30 PM – 4:30 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner on Central Avenue, then a stroll past the historic railway depot. Summer evenings bring free concerts to Depot Park.","stop":"Downtown Whitefish","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$30–$60/person (est.)","description":"Ride the scenic gondola to the 7,000-foot summit for panoramic views stretching to Glacier National Park. Race the alpine slide back down, or try the zip line tour for bigger thrills.","stop":"Whitefish Mountain Resort","time":"9:30 AM – 12:30 PM"},"title":"Mountain Thrills"},{"afternoon":{"cost":"$20–$40 for rentals (est.)","description":"Rent paddleboards or kayaks, or just swim from the sandy city beach. The Whitefish Trail's lakeside section is perfect for a family bike ride. The water is brisk but beautiful.","stop":"Whitefish Lake","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"Free (est.)","description":"Sunset from the city beach is a Whitefish ritual — bring a blanket and takeout. The alpenglow on the peaks is unforgettable.","stop":"Sunset at the lake","time":"6:30 PM – 8:00 PM"},"morning":{"cost":"Free to explore (est.)","description":"Browse the galleries, bookstores, and western shops of Central Avenue. The Tuesday farmers' market (seasonal) is a highlight. Pick up huckleberry treats.","stop":"Downtown Whitefish","time":"10:00 AM – 12:30 PM"},"title":"Lake Day"},{"afternoon":{"cost":"Included with park pass; gas extra (est.)","description":"Glacier's west entrance is 30 minutes away — Lake McDonald and the lower Sun Road make a perfect final adventure. Or linger: one more lake swim and a relaxed departure.","stop":"Glacier National Park day trip (optional)","time":"12:00 PM – 5:00 PM"},"day":3,"evening":{"cost":"Gas only (est.)","description":"Kalispell airport is 20 minutes south. If driving, US-93 and US-2 connect easily to I-90.","stop":"Drive home","time":"3:00 PM – 5:00 PM"},"morning":{"cost":"Free (est.)","description":"A slow morning: breakfast downtown, a final lakeside walk, and browsing the shops. Whitefish is the kind of town families promise to return to.","stop":"Farewell Whitefish","time":"9:00 AM – 12:00 PM"},"title":"Farewell"}],"lat":48.41061,"lng":-114.33722,"overview":"Whitefish is the perfect Glacier gateway town — a mountain resort with summer gondolas and alpine slides, a pristine lake with a sandy beach, and a storybook downtown built around the railway. Families get big-mountain adventure with small-town ease, plus Glacier National Park 30 minutes away. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Stumptown Art Studio (family art classes)","Whitefish Museum (railway history)","Alpine Theatre Project (summer shows)"],"region":"Flathead Valley","related":["glacier-mt-park","missoula-mt-river","bozeman-mt-mountain"],"restaurants":[{"detail":"Lively spot with great burgers and Montana brews.","name":"The Great Northern Bar & Grill","price":"$$"},{"detail":"Beloved local pizzeria, perfect for tired families.","name":"Jersey Boys Pizzeria","price":"$"},{"detail":"Upscale-but-welcoming spot with mountain views.","name":"Tupelo Grille","price":"$$$"}],"state":"MT","stateName":"Montana","tagline":"Glacier's charming gateway — gondolas, alpine slides, and a storybook lake town.","title":"Whitefish, MT: Three-Day Alpine Retreat","tripType":"alpine retreat","imageAsset":"assets/plains-north/images/whitefish-mt-alpine/hero.jpg"},{"attractions":[{"description":"America's first destination ski resort, still glamorous after 90 years. Summer brings the gondola, mountain biking, and the famous outdoor ice rink. The Sun Valley Lodge and village are fun to explore even if you never ski. Hemingway's memorial sits nearby in Ketchum.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sun%20Valley%20Resort%20Sun%20Valley%20ID","name":"Sun Valley Resort","officialUrl":"https://www.sunvalley.com/","photos":["assets/plains-north/images/sun-valley-id-mountain/attr1-1.jpg","assets/plains-north/images/sun-valley-id-mountain/attr1-2.jpg","assets/plains-north/images/sun-valley-id-mountain/attr1-3.jpg","assets/plains-north/images/sun-valley-id-mountain/attr1-4.jpg"],"price":"$30–$60/person summer activities (est.)"},{"description":"A 756,000-acre wonderland of jagged peaks, alpine lakes, and hot springs, all within an easy drive. The Stanley Basin viewpoint offers the classic Sawtooth photo. Families love the easy trails and the free, uncrowded feel.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sawtooth%20National%20Recreation%20Area%20Stanley%20ID","name":"Sawtooth National Recreation Area","officialUrl":"https://www.fs.usda.gov/recarea/sawtooth/recarea/?recid=5844","photos":["assets/plains-north/images/sun-valley-id-mountain/attr2-1.jpg","assets/plains-north/images/sun-valley-id-mountain/attr2-2.jpg","assets/plains-north/images/sun-valley-id-mountain/attr2-3.jpg","assets/plains-north/images/sun-valley-id-mountain/attr2-4.jpg"],"price":"Free (est.)"},{"description":"Ketchum's main street blends western charm with upscale mountain culture — galleries, bookstores, and the famous Pioneer Saloon. The Sun Valley Museum of History (free) tells the resort's glamorous story. A great evening stroll.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Downtown%20Ketchum%20ID","name":"Downtown Ketchum","officialUrl":"https://www.visitsunvalley.com/","photos":["assets/plains-north/images/sun-valley-id-mountain/attr3-1.jpg","assets/plains-north/images/sun-valley-id-mountain/attr3-2.jpg","assets/plains-north/images/sun-valley-id-mountain/attr3-3.jpg","assets/plains-north/images/sun-valley-id-mountain/attr3-4.jpg"],"price":"Free to explore (est.)"},{"description":"The moving memorial to Ernest Hemingway, who lived and died in Ketchum, sits along the Big Wood River with mountain views. The short walk from the Sun Valley Lodge area is peaceful and scenic. A quick, meaningful stop for older kids.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Ernest%20Hemingway%20Memorial%20Ketchum%20ID","name":"Ernest Hemingway Memorial","officialUrl":"https://comlib.org/","photos":["assets/plains-north/images/sun-valley-id-mountain/attr4-1.jpg","assets/plains-north/images/sun-valley-id-mountain/attr4-2.jpg","assets/plains-north/images/sun-valley-id-mountain/attr4-3.jpg","assets/plains-north/images/sun-valley-id-mountain/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"June–October","budget":1000,"budgetNote":"Estimate for 2 adults + 2 kids: resort activities, meals, and gas; lodging not included.","days":3,"destination":"Sun Valley, ID","driveNotes":"Sun Valley/Ketchum is 3 hours from Boise via ID-75 through the scenic Wood River Valley. The Sawtooth NRA's Stanley Basin is an hour north on ID-75 — an easy day trip. Summer weekends book up; reserve resort activities ahead. Winter transforms it into a ski trip instead.","familyFriendly":"Best for ages 5+. Gondola rides and easy trails suit all ages; summer ice skating delights kids.","heroPhoto":"assets/plains-north/images/sun-valley-id-mountain/hero.jpg","highlights":["Ride the gondola at America's first ski resort","See the jagged Sawtooths from the Stanley Basin overlook","Skate the famous outdoor ice rink in summer","Stroll Ketchum's galleries and western shops","Visit the Hemingway Memorial by the Big Wood River"],"id":"sun-valley-id-mountain","interests":["family","outdoors","scenic","nature"],"itinerary":[{"afternoon":{"cost":"$20–$40/person (est.)","description":"Lace up for a public skate session at the iconic outdoor rink — skating under mountain peaks in summer is pure magic. Rentals are available on-site. The village shops and ice cream round out the afternoon.","stop":"Sun Valley ice skating & village","time":"1:30 PM – 4:30 PM"},"day":1,"evening":{"cost":"Free (est.)","description":"Walk the peaceful path along the Big Wood River to the Hemingway Memorial. Dinner in Ketchum afterward — the town's restaurants range from casual to celebratory.","stop":"Hemingway Memorial & Ketchum dinner","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$30–$60/person (est.)","description":"Ride the gondola up Bald Mountain for sweeping valley views, then explore the summit trails. Summer brings wildflowers and mountain bikers. The lodge area has lawn games and a great lunch spot.","stop":"Sun Valley Resort gondola & summit","time":"9:30 AM – 12:30 PM"},"title":"Resort Day"},{"afternoon":{"cost":"Free (est.)","description":"Picnic at the Stanley Basin viewpoint with the Sawtooths towering overhead — one of the great mountain views in America. Dip toes in alpine creeks and let the kids scramble on safe boulders.","stop":"Stanley Basin viewpoint & picnic","time":"1:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Back in Ketchum for dinner and the free Sun Valley Museum of History. Summer evenings often bring outdoor concerts to the village lawn.","stop":"Ketchum evening","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"Free; gas extra (est.)","description":"Drive an hour north into the Sawtooth National Recreation Area. The easy Fishhook Creek trail or the viewpoint pullouts give big scenery with little effort. Watch for elk and mountain goats.","stop":"Sawtooth National Recreation Area","time":"9:00 AM – 12:30 PM"},"title":"Sawtooth Day Trip"},{"afternoon":{"cost":"Gas only (est.)","description":"The drive back to Boise down the Wood River Valley is lovely — stop in Hailey for lunch and the antique shops. Three hours door to door.","stop":"Drive home","time":"1:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Most families drive back to Boise or fly from Sun Valley's small airport. Leave with huckleberry treats and mountain memories.","stop":"Farewell","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free to explore (est.)","description":"A slow final morning on Ketchum's main street — galleries, bookstores, and the Pioneer Saloon's famous history. Brunch before checkout.","stop":"Downtown Ketchum","time":"9:30 AM – 12:00 PM"},"title":"Farewell"}],"lat":43.6922,"lng":-114.34622,"overview":"Sun Valley is America's original ski resort town — glamorous but genuinely welcoming, with summer gondolas, outdoor ice skating, and the jagged Sawtooths an hour north. Ketchum's western-meets-upscale vibe makes every evening fun. Three days mix resort ease with real mountain adventure. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Sun Valley Museum of History (free)","Wood River Museum (Ketchum)","Sun Valley ice rink (covered sessions)"],"region":"Wood River Valley","related":["stanley-id-sawtooths","boise-id-city","jackson-wy-teton"],"restaurants":[{"detail":"Famous Ketchum saloon with steaks and western history on the walls.","name":"Pioneer Saloon","price":"$$"},{"detail":"Beloved no-frills burger joint, a Ketchum institution since 1978.","name":"Grumpy's","price":"$"},{"detail":"Upscale mountain dining with a warm, family-welcoming feel.","name":"The Roundhouse","price":"$$$"}],"state":"ID","stateName":"Idaho","tagline":"America's first ski resort — gondolas, ice skating, and the jagged Sawtooths.","title":"Sun Valley, ID: Three-Day Mountain Retreat","tripType":"mountain retreat","imageAsset":"assets/plains-north/images/sun-valley-id-mountain/hero.jpg"},{"attractions":[{"description":"Scenic narrated cruises on one of America's most beautiful lakes, from 90-minute tours to sunset dinner cruises. The captain's stories cover the lake's logging history and lakeside mansions. Kids love the open decks and eagle sightings.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake%20Coeur%20d%27Alene%20Cruises%20Coeur%20d%27Alene%20ID","name":"Lake Coeur d'Alene Cruises","officialUrl":"https://www.cdacruises.com/","photos":["assets/plains-north/images/coeur-dalene-id-lake/attr1-1.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr1-2.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr1-3.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr1-4.jpg"],"price":"$28/adult, $14/child (est.)"},{"description":"A 165-acre lakeside park minutes from downtown, with the easy 2.3-mile Tubbs Hill loop trail. The trail dips to hidden beaches perfect for swimming. Old-growth cedars and lake views make it feel wild despite the location.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tubbs%20Hill%20Coeur%20d%27Alene%20ID","name":"Tubbs Hill","officialUrl":"https://www.cdaid.org/","photos":["assets/plains-north/images/coeur-dalene-id-lake/attr2-1.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr2-2.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr2-3.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr2-4.jpg"],"price":"Free (est.)"},{"description":"The Northwest's largest theme park, 20 minutes north in Athol, with 70+ rides including world-class roller coasters and the Boulder Beach water park. A full day easily — arrive at opening and stay for the evening shows. Great for thrill-seeking families.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Silverwood%20Theme%20Park%20Athol%20ID","name":"Silverwood Theme Park","officialUrl":"https://www.silverwoodthemepark.com/","photos":["assets/plains-north/images/coeur-dalene-id-lake/attr3-1.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr3-2.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr3-3.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr3-4.jpg"],"price":"$80/person (est.)"},{"description":"Coeur d'Alene's lively main street along the lake, with the famous floating boardwalk — the world's longest — and the grand Coeur d'Alene Resort. Shops, ice cream, and sunset views make every evening pleasant. Summer brings free concerts to the park.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Downtown%20Coeur%20d%27Alene%20ID","name":"Downtown Coeur d'Alene & the Boardwalk","officialUrl":"https://www.coeurdalene.org/","photos":["assets/plains-north/images/coeur-dalene-id-lake/attr4-1.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr4-2.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr4-3.jpg","assets/plains-north/images/coeur-dalene-id-lake/attr4-4.jpg"],"price":"Free to explore (est.)"}],"bestSeason":"June–September","budget":1100,"budgetNote":"Estimate for 2 adults + 2 kids: cruise, theme park tickets, meals, and gas; lodging not included.","days":3,"destination":"Coeur d'Alene, ID","driveNotes":"Coeur d'Alene is on I-90, 30 minutes from Spokane and its airport. Silverwood is 20 minutes north on US-95 — buy tickets online to save. Downtown parking is metered but easy; the lake cruises depart from the resort marina.","familyFriendly":"Best for ages 4+. Silverwood has rides for toddlers to teens; the lake and Tubbs Hill suit all ages.","heroPhoto":"assets/plains-north/images/coeur-dalene-id-lake/hero.jpg","highlights":["Cruise stunning Lake Coeur d'Alene","Hike Tubbs Hill to hidden swimming beaches","Ride coasters at Silverwood Theme Park","Walk the world's longest floating boardwalk","Watch the sunset from downtown's lakeside park"],"id":"coeur-dalene-id-lake","interests":["family","outdoors","nature","amusement-parks","scenic"],"itinerary":[{"afternoon":{"cost":"$28/adult, $14/child (est.)","description":"Board a narrated scenic cruise from the resort marina. The 90-minute tour covers the lake's logging history, eagle nests, and lakeside mansions. Kids love the open upper deck.","stop":"Lake Coeur d'Alene scenic cruise","time":"2:00 PM – 4:00 PM"},"day":1,"evening":{"cost":"Free (est.)","description":"Stroll the floating boardwalk — the world's longest — as the sun sets over the lake. Dinner downtown, then ice cream on the beach. A perfect first evening.","stop":"Boardwalk sunset & downtown dinner","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"Free (est.)","description":"Hike the easy 2.3-mile Tubbs Hill loop, dipping down to hidden beaches for a swim. The old-growth cedars and lake views feel worlds away from town. Pack a picnic.","stop":"Tubbs Hill","time":"9:30 AM – 12:30 PM"},"title":"Lake Day"},{"afternoon":{"cost":"Included with admission (est.)","description":"Cool off at Boulder Beach water park inside Silverwood — slides, a lazy river, and a wave pool. Then back to the rides for the evening, when lines shrink and the park glows.","stop":"Silverwood, continued","time":"1:00 PM – 6:00 PM"},"day":2,"evening":{"cost":"$50–$70 for dinner (est.)","description":"A tired, happy drive back to Coeur d'Alene for dinner. The kids will sleep well tonight.","stop":"Dinner in Coeur d'Alene","time":"6:30 PM – 8:00 PM"},"morning":{"cost":"$80/person (est.)","description":"The big day: the Northwest's largest theme park, 20 minutes north. Arrive at opening for the coasters, then mix in the water park. Buy tickets online in advance — it's cheaper and skips the line.","stop":"Silverwood Theme Park","time":"10:00 AM – 1:00 PM"},"title":"Theme Park Day"},{"afternoon":{"cost":"Gas only (est.)","description":"Spokane is 30 minutes west on I-90 with an airport and all services. A relaxed afternoon departure works for most families.","stop":"Drive home","time":"2:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"One last boardwalk stroll and you're off. Coeur d'Alene is the kind of place families come back to year after year.","stop":"Farewell","time":"4:00 PM – 5:00 PM"},"morning":{"cost":"Free to explore (est.)","description":"A slow final morning: breakfast downtown, browsing Sherman Avenue's shops, and one last lakeside walk. Pick up huckleberry souvenirs.","stop":"Downtown Coeur d'Alene","time":"9:30 AM – 12:30 PM"},"title":"Farewell"}],"lat":47.67169,"lng":-116.77581,"overview":"Coeur d'Alene pairs one of America's prettiest lakes with the Northwest's biggest theme park — a combination kids adore. Cruise the lake, hike to hidden beaches, ride world-class coasters at Silverwood, and stroll the famous floating boardwalk at sunset. Three days here are pure family fun. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Museum of North Idaho","Silverwood's indoor shows (seasonal)","Spokane's Mobius Discovery Center (30 min away)"],"region":"Idaho Panhandle","related":["boise-id-city","whitefish-mt-alpine","stanley-id-sawtooths"],"restaurants":[{"detail":"Lakeside fine dining at the resort with mountain views.","name":"Beverly's","price":"$$$"},{"detail":"Fun downtown spot with burgers and local brews.","name":"Crafted Tap House","price":"$$"},{"detail":"Classic family pizza joint the kids will love.","name":"Fire Artisan Pizza","price":"$"}],"state":"ID","stateName":"Idaho","tagline":"A sparkling lake, a giant theme park, and the world's longest floating boardwalk.","title":"Coeur d'Alene, ID: Three-Day Lakeside Getaway","tripType":"lakeside getaway","imageAsset":"assets/plains-north/images/coeur-dalene-id-lake/hero.jpg"},{"attractions":[{"description":"A 25-mile paved greenbelt following the Boise River through the heart of the city. Rent bikes, spot deer and herons, and stop at riverside parks. The path is flat, shaded, and perfect for families — you can ride for miles without crossing traffic.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Boise%20River%20Greenbelt%20Boise%20ID","name":"Boise River Greenbelt","officialUrl":"https://www.cityofboise.org/","photos":["assets/plains-north/images/boise-id-city/attr1-1.jpg","assets/plains-north/images/boise-id-city/attr1-2.jpg","assets/plains-north/images/boise-id-city/attr1-3.jpg","assets/plains-north/images/boise-id-city/attr1-4.jpg"],"price":"Free; bike rentals ~$15/hr (est.)"},{"description":"A compact, well-loved zoo in Julia Davis Park with 200+ animals, including snow leopards, giraffes, and penguins. The butterfly exhibit and zoo train are kid favorites. Easy to do in half a day.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Zoo%20Boise%20Boise%20ID","name":"Zoo Boise","officialUrl":"https://zooboise.org/","photos":["assets/plains-north/images/boise-id-city/attr2-1.jpg","assets/plains-north/images/boise-id-city/attr2-2.jpg","assets/plains-north/images/boise-id-city/attr2-3.jpg","assets/plains-north/images/boise-id-city/attr2-4.jpg"],"price":"$12/adult, $8/child (est.)"},{"description":"Idaho's state history museum downtown, with immersive exhibits on the state's Native peoples, pioneers, and wild landscapes. The hands-on discovery areas and a recreated 1800s town engage kids. A great air-conditioned anchor.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Idaho%20State%20Museum%20Boise%20ID","name":"Idaho State Museum","officialUrl":"https://history.idaho.gov/","photos":["assets/plains-north/images/boise-id-city/attr3-1.jpg","assets/plains-north/images/boise-id-city/attr3-2.jpg","assets/plains-north/images/boise-id-city/attr3-3.jpg","assets/plains-north/images/boise-id-city/attr3-4.jpg"],"price":"$10/adult, $5/child (est.)"},{"description":"Boise's backyard mountain, 16 miles up a scenic road, with summer chairlift rides, mountain biking, and hiking. The lift-served views stretch across the Treasure Valley. In winter it's the city's beloved ski hill.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bogus%20Basin%20Boise%20ID","name":"Bogus Basin Mountain Recreation Area","officialUrl":"https://bogusbasin.org/","photos":["assets/plains-north/images/boise-id-city/attr4-1.jpg","assets/plains-north/images/boise-id-city/attr4-2.jpg","assets/plains-north/images/boise-id-city/attr4-3.jpg","assets/plains-north/images/boise-id-city/attr4-4.jpg"],"price":"$20–$35/person summer activities (est.)"}],"bestSeason":"May–October","budget":800,"budgetNote":"Estimate for 2 adults + 2 kids: attraction tickets, bike rentals, meals, and gas; lodging not included.","days":3,"destination":"Boise, ID","driveNotes":"Boise is on I-84 in southwestern Idaho, 7 hours from Salt Lake City and 8 from Portland. Everything here is within 20 minutes. Downtown parking garages are cheap; the Greenbelt is best accessed from Julia Davis Park. Summer highs hit the 90s — plan water activities midday.","familyFriendly":"Best for ages 4+. The Greenbelt is flat and stroller-friendly; the zoo and discovery center delight younger kids.","heroPhoto":"assets/plains-north/images/boise-id-city/hero.jpg","highlights":["Bike the 25-mile Boise River Greenbelt","Meet snow leopards and giraffes at Zoo Boise","Explore Idaho history at the State Museum","Ride the summer chairlift at Bogus Basin","Float the Boise River through town (summer)"],"id":"boise-id-city","interests":["family","museums","outdoors","food","nature"],"itinerary":[{"afternoon":{"cost":"$12/adult, $8/child (est.)","description":"Walk to the adjacent Zoo Boise in Julia Davis Park. The 200+ animals, butterfly house, and train ride fill a happy afternoon. Shaded paths keep it comfortable.","stop":"Zoo Boise","time":"1:30 PM – 4:00 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner downtown — Boise's restaurant scene is excellent. The Basque Block's unique cuisine is a fun family adventure.","stop":"Downtown Boise dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Free; rentals ~$15/hr (est.)","description":"Rent bikes and ride the Greenbelt's most scenic stretch from Julia Davis Park. The flat, shaded path follows the river past parks and wildlife. Stop for a playground break — the kids set the pace.","stop":"Boise River Greenbelt","time":"9:30 AM – 12:30 PM"},"title":"River & Zoo"},{"afternoon":{"cost":"Free to explore (est.)","description":"Wander the Basque Block — Boise has the largest Basque community outside Spain — and browse the shops. The free Idaho State Capitol tour is a quick, impressive stop.","stop":"Basque Block & Capitol","time":"1:30 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free to browse (est.)","description":"Boise's downtown stays lively into the evening with street performers in summer. Grab dessert and enjoy the warm night.","stop":"Downtown evening","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$10/adult, $5/child (est.)","description":"Idaho's state museum brings the state's story to life with a recreated pioneer town and hands-on exhibits. Kids love the discovery areas. Plan 2–3 hours.","stop":"Idaho State Museum","time":"10:00 AM – 12:30 PM"},"title":"Museums & Culture"},{"afternoon":{"cost":"Gas only (est.)","description":"Boise's airport has direct flights nationwide. If driving, I-84 connects east to Twin Falls and west to Oregon.","stop":"Drive home","time":"2:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"One last Greenbelt sunset walk and you're off. Boise is easy to reach and hard to leave.","stop":"Farewell","time":"4:00 PM – 5:00 PM"},"morning":{"cost":"$20–$35/person (est.)","description":"Drive 16 miles up to Bogus Basin for summer chairlift rides and mountaintop views. The alpine scenery and cool air are a refreshing final morning.","stop":"Bogus Basin","time":"9:00 AM – 12:00 PM"},"title":"Mountain Morning"}],"lat":43.60764,"lng":-116.1934,"overview":"Boise is the friendly, outdoorsy capital of Idaho — a 25-mile riverside bike path, a beloved zoo, and a mountain recreation area 16 miles from downtown. The food scene punches above its weight, and the Basque Block adds unique culture. Three days here are relaxed, affordable, and full of fresh air. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Idaho State Museum","Discovery Center of Idaho (hands-on science)","Zoo Boise (covered exhibits)"],"region":"Treasure Valley","related":["twin-falls-id-waterfalls","sun-valley-id-mountain","coeur-dalene-id-lake"],"restaurants":[{"detail":"Boise institution for Basque comfort food on the Basque Block.","name":"Bar Gernika","price":"$"},{"detail":"Lively downtown spot with great burgers and local brews.","name":"Bittercreek Alehouse","price":"$$"},{"detail":"Beloved breakfast joint with legendary pancakes.","name":"Goldy's Breakfast Bistro","price":"$"}],"state":"ID","stateName":"Idaho","tagline":"Idaho's friendly capital — riverside bike paths, a great zoo, and mountain air.","title":"Boise, ID: Three-Day City Adventure","tripType":"city adventure","imageAsset":"assets/plains-north/images/boise-id-city/hero.jpg"},{"attractions":[{"description":"The crown jewel of the Sawtooths — a stunning alpine lake with sandy beaches, boat rentals, and the jagged peaks reflected in the water. The easy Lakeshore Trail suits families. Arrive early on summer weekends; it's popular for good reason.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Redfish%20Lake%20Stanley%20ID","name":"Redfish Lake","officialUrl":"https://www.fs.usda.gov/recarea/sawtooth/recarea/?recid=5844","photos":["assets/plains-north/images/stanley-id-sawtooths/attr1-1.jpg","assets/plains-north/images/stanley-id-sawtooths/attr1-2.jpg","assets/plains-north/images/stanley-id-sawtooths/attr1-3.jpg","assets/plains-north/images/stanley-id-sawtooths/attr1-4.jpg"],"price":"Free; parking pass ~$5 (est.)"},{"description":"A picture-perfect alpine lake under the Sawtooth peaks, with a gentle shoreline trail and great picnic spots. The drive in along Stanley Lake Road offers classic mountain views. Less crowded than Redfish — a local favorite.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Stanley%20Lake%20Stanley%20ID","name":"Stanley Lake","officialUrl":"https://www.fs.usda.gov/recarea/sawtooth/recarea/?recid=5844","photos":["assets/plains-north/images/stanley-id-sawtooths/attr2-1.jpg","assets/plains-north/images/stanley-id-sawtooths/attr2-2.jpg","assets/plains-north/images/stanley-id-sawtooths/attr2-3.jpg","assets/plains-north/images/stanley-id-sawtooths/attr2-4.jpg"],"price":"Free (est.)"},{"description":"One of America's great wild rivers, running right past Stanley. Family float trips with local outfitters offer gentle rapids and stunning scenery — no experience needed. The riverbanks are also great for fishing and picnics.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Salmon%20River%20Stanley%20ID","name":"Salmon River","officialUrl":"https://www.fs.usda.gov/recarea/sawtooth/recarea/?recid=5844","photos":["assets/plains-north/images/stanley-id-sawtooths/attr3-1.jpg","assets/plains-north/images/stanley-id-sawtooths/attr3-2.jpg","assets/plains-north/images/stanley-id-sawtooths/attr3-3.jpg","assets/plains-north/images/stanley-id-sawtooths/attr3-4.jpg"],"price":"$60–$90/person guided float (est.)"},{"description":"The tiny town at the heart of it all — population around 100 — with rustic lodges, hot springs nearby, and the famous Stanley Baking Co. for breakfast. The whole town faces the Sawtooth range, so every view is a postcard.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Downtown%20Stanley%20ID","name":"Downtown Stanley","officialUrl":"https://www.stanleycc.org/","photos":["assets/plains-north/images/stanley-id-sawtooths/attr4-1.jpg","assets/plains-north/images/stanley-id-sawtooths/attr4-2.jpg","assets/plains-north/images/stanley-id-sawtooths/attr4-3.jpg","assets/plains-north/images/stanley-id-sawtooths/attr4-4.jpg"],"price":"Free to explore (est.)"}],"bestSeason":"July–September","budget":850,"budgetNote":"Estimate for 2 adults + 2 kids: float trip, meals, and gas; lodging not included.","days":3,"destination":"Stanley, ID","driveNotes":"Stanley is remote — 3 hours from Boise, 2 from Sun Valley, 4 from Idaho Falls. Fill up gas before you go; the town has limited services. The season is short (July–September); snow can linger into July at the lakes. Cell service is spotty — download maps offline.","familyFriendly":"Best for ages 6+. Alpine lakes are cold and the altitude is 6,000+ feet — pace yourselves and bring layers.","heroPhoto":"assets/plains-north/images/stanley-id-sawtooths/hero.jpg","highlights":["Swim in crystal-clear Redfish Lake under the Sawtooths","Picnic at peaceful Stanley Lake","Float the wild Salmon River with a guide","Soak in natural hot springs near town","Stargaze under some of America's darkest skies"],"id":"stanley-id-sawtooths","interests":["family","outdoors","nature","scenic"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Walk the easy Lakeshore Trail, rent a kayak, or just swim from the sandy beach. The Sawtooth peaks reflected in the water are unforgettable. Pack a picnic — the lodge's restaurant is the other option.","stop":"Redfish Lake, continued","time":"1:00 PM – 4:30 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner in tiny Stanley, then step outside for the stars. Stanley has some of the darkest skies in America — the Milky Way is vivid on clear nights.","stop":"Dinner & stargazing in Stanley","time":"6:00 PM – 9:00 PM"},"morning":{"cost":"Free; parking ~$5 (est.)","description":"Drive 20 minutes south to Redfish Lake, the Sawtooths' crown jewel. The sandy beach and shallow entry are great for kids, and the mountain backdrop is unreal. Arrive by 10 AM for parking.","stop":"Redfish Lake","time":"10:00 AM – 12:30 PM"},"title":"Redfish Lake"},{"afternoon":{"cost":"$60–$90/person (est.)","description":"Join a guided family float on the Salmon River — gentle rapids, big scenery, and guides who handle everything. No experience needed; wetsuits provided. Kids must meet age minimums — check when booking.","stop":"Salmon River float trip","time":"1:00 PM – 4:30 PM"},"day":2,"evening":{"cost":"Free (est.)","description":"Soak in one of the natural hot springs near town — several are free and riverside. A perfect end to an active day. Bring towels and water shoes.","stop":"Hot springs soak","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Free (est.)","description":"Head to Stanley Lake for a quieter alpine morning. The shoreline trail is gentle, the picnic spots are perfect, and the peak reflections are gorgeous. A local favorite for good reason.","stop":"Stanley Lake","time":"9:30 AM – 12:30 PM"},"title":"Lakes & River"},{"afternoon":{"cost":"Gas only (est.)","description":"The drive out — south to Sun Valley or west to Boise — is scenic but long. Depart after lunch for an easy travel day.","stop":"Drive home","time":"1:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Stanley is remote and magical — families leave promising to return. The Sawtooths will be waiting.","stop":"Farewell","time":"4:00 PM – 5:00 PM"},"morning":{"cost":"$10–$20 for breakfast (est.)","description":"Breakfast at the famous Stanley Baking Co. — worth the wait — then one last walk with Sawtooth views. Browse the tiny shops for souvenirs.","stop":"Downtown Stanley","time":"9:00 AM – 12:00 PM"},"title":"Farewell"}],"lat":44.21717,"lng":-114.93644,"overview":"Stanley is Idaho's mountain soul — a town of 100 people beneath the jagged Sawtooth peaks, with alpine lakes so clear they look Photoshopped. Families come for Redfish Lake's beaches, gentle river floats, and night skies full of stars. It's remote, so plan ahead — but the payoff is pure wilderness magic. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Stanley Museum","Redfish Lake Lodge (games + restaurant)","Sawtooth Luce's hot springs (covered pools)"],"region":"Sawtooth Country","related":["sun-valley-id-mountain","boise-id-city","jackson-wy-teton"],"restaurants":[{"detail":"Famous for mountain breakfasts worth the wait.","name":"Stanley Baking Co.","price":"$"},{"detail":"Rustic lodge dining with Sawtooth views.","name":"Redfish Lake Lodge Restaurant","price":"$$"},{"detail":"Casual burgers and brews in downtown Stanley.","name":"Sawtooth Luce's","price":"$"}],"state":"ID","stateName":"Idaho","tagline":"Idaho's mountain soul — alpine lakes, wild rivers, and the darkest skies in America.","title":"Stanley, ID: Three-Day Sawtooth Escape","tripType":"sawtooth escape","imageAsset":"assets/plains-north/images/stanley-id-sawtooths/hero.jpg"},{"attractions":[{"description":"The 'Niagara of the West' — 212 feet tall and 900 feet wide, taller than Niagara Falls. Spring snowmelt brings thundering flows; summer evenings feature light shows. The overlooks and visitor center are excellent, and the canyon views are free.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Shoshone%20Falls%20Twin%20Falls%20ID","name":"Shoshone Falls","officialUrl":"https://www.tfid.org/","photos":["assets/plains-north/images/twin-falls-id-waterfalls/attr1-1.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr1-2.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr1-3.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr1-4.jpg"],"price":"$5/vehicle (est.)"},{"description":"The 486-foot-high bridge spanning the Snake River Canyon — famous for BASE jumpers leaping from its pedestrian walkway. The visitor center explains the canyon's geology, and the views straight down are thrilling. Watch jumpers on calm mornings.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Perrine%20Bridge%20Twin%20Falls%20ID","name":"Perrine Bridge","officialUrl":"https://visitidaho.org/","photos":["assets/plains-north/images/twin-falls-id-waterfalls/attr2-1.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr2-2.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr2-3.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr2-4.jpg"],"price":"Free (est.)"},{"description":"The 500-foot-deep canyon carved by the Snake River, with rim trails, overlooks, and the scenic Canyon Rim Trail. The visitor center at the bridge explains the geology. Golden hour light on the canyon walls is spectacular.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Snake%20River%20Canyon%20Twin%20Falls%20ID","name":"Snake River Canyon","officialUrl":"https://visitidaho.org/","photos":["assets/plains-north/images/twin-falls-id-waterfalls/attr3-1.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr3-2.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr3-3.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr3-4.jpg"],"price":"Free (est.)"},{"description":"The College of Southern Idaho's museum, planetarium, and observatory — with a real mammoth skeleton, art galleries, and family science programs. The planetarium shows are a hit with kids. A great rainy-day or evening option.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Herrett%20Center%20Twin%20Falls%20ID","name":"Herrett Center for Arts and Science","officialUrl":"https://herrett.csi.edu/","photos":["assets/plains-north/images/twin-falls-id-waterfalls/attr4-1.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr4-2.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr4-3.jpg","assets/plains-north/images/twin-falls-id-waterfalls/attr4-4.jpg"],"price":"$6/adult, $4/child (est.)"}],"bestSeason":"April–October","budget":550,"budgetNote":"Estimate for 2 adults + 2 kids: attraction fees, meals, and gas; lodging not included.","days":2,"destination":"Twin Falls, ID","driveNotes":"Twin Falls is on I-84, 2 hours from Boise and 3.5 from Salt Lake City. Shoshone Falls is 10 minutes east of town — check flow levels online, as irrigation can reduce summer flows. The canyon rim trails are paved and easy; keep kids back from unfenced edges.","familyFriendly":"Best for ages 4+. The falls and bridge thrill all ages; keep little ones close at canyon overlooks.","heroPhoto":"assets/plains-north/images/twin-falls-id-waterfalls/hero.jpg","highlights":["Stand before 212-foot Shoshone Falls","Watch BASE jumpers leap from the Perrine Bridge","Walk the scenic Canyon Rim Trail","Explore the Herrett Center's planetarium","See the canyon glow at golden hour"],"id":"twin-falls-id-waterfalls","interests":["family","nature","scenic","outdoors","museums"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Walk the paved Canyon Rim Trail from the visitor center, with jaw-dropping views into the 500-foot gorge. Watch for BASE jumpers on calm days — kids are mesmerized. The trail is stroller-friendly.","stop":"Perrine Bridge & Canyon Rim Trail","time":"1:30 PM – 4:00 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner in Twin Falls, then an evening planetarium show at the Herrett Center if the timing works. A fun, educational nightcap.","stop":"Dinner & planetarium","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$5/vehicle (est.)","description":"Head straight to the 'Niagara of the West' — 212 feet of thundering water (best in spring). The overlooks, trails, and visitor center easily fill a morning. Picnic areas have canyon views.","stop":"Shoshone Falls","time":"9:30 AM – 12:30 PM"},"title":"Falls & Canyon"},{"afternoon":{"cost":"$6/adult, $4/child (est.)","description":"The College of Southern Idaho's museum has a real mammoth, art galleries, and an excellent planetarium. A perfect cool, indoor afternoon before the drive home.","stop":"Herrett Center for Arts and Science","time":"1:00 PM – 3:30 PM"},"day":2,"evening":{"cost":"Gas only (est.)","description":"Twin Falls is 2 hours from Boise on I-84. An afternoon departure gets you home for dinner.","stop":"Drive home","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free (est.)","description":"Return to the canyon rim for a morning walk in the golden light. Dierkes Lake, hidden in the canyon near Shoshone Falls, offers swimming and rock jumping for adventurous families.","stop":"Canyon rim morning & Dierkes Lake","time":"9:30 AM – 12:00 PM"},"title":"Canyon Morning"}],"lat":42.55619,"lng":-114.4696,"overview":"Twin Falls is built around drama — a 212-foot waterfall taller than Niagara, a 500-foot canyon, and a bridge where BASE jumpers leap into the gorge. It's an easy, affordable two-day stop on I-84 with big wow-factor for kids. Come in spring for the falls at full thunder. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Herrett Center for Arts and Science","Twin Falls Public Library (family programs)","Magic Valley Mall (play areas)"],"region":"Magic Valley","related":["boise-id-city","stanley-id-sawtooths","sun-valley-id-mountain"],"restaurants":[{"detail":"Cabin-themed diner with giant portions and all-day breakfast.","name":"Black Bear Diner","price":"$"},{"detail":"Canyon-rim dining with steakhouse classics.","name":"Elevation 486","price":"$$"},{"detail":"Family-friendly Mexican restaurant downtown.","name":"La Fiesta Mexican Restaurant","price":"$"}],"state":"ID","stateName":"Idaho","tagline":"The Niagara of the West — towering falls, a canyon bridge, and BASE jumpers.","title":"Twin Falls, ID: Two-Day Waterfall Stop","tripType":"waterfall stop","imageAsset":"assets/plains-north/images/twin-falls-id-waterfalls/hero.jpg"},{"attractions":[{"description":"The world's first national park, with half the planet's geysers and wildlife that stops traffic. Old Faithful, the Grand Prismatic Spring, and the Grand Canyon of the Yellowstone are the headline acts. Give it time — the park is bigger than Rhode Island and Delaware combined.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Yellowstone%20National%20Park","name":"Yellowstone National Park","officialUrl":"https://www.nps.gov/yell/","photos":["assets/plains-north/images/yellowstone-wy-park/attr1-1.jpg","assets/plains-north/images/yellowstone-wy-park/attr1-2.jpg","assets/plains-north/images/yellowstone-wy-park/attr1-3.jpg","assets/plains-north/images/yellowstone-wy-park/attr1-4.jpg"],"price":"$35/vehicle, 7-day pass (est.)"},{"description":"The park's most famous geyser, erupting roughly every 90 minutes to 130 feet. The visitor center predicts eruptions, and the boardwalks around the Upper Geyser Basin hold dozens more geysers. Arrive 30 minutes early for a good viewing spot.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Old%20Faithful%20Yellowstone%20National%20Park","name":"Old Faithful","officialUrl":"https://www.nps.gov/yell/","photos":["assets/plains-north/images/yellowstone-wy-park/attr2-1.jpg","assets/plains-north/images/yellowstone-wy-park/attr2-2.jpg","assets/plains-north/images/yellowstone-wy-park/attr2-3.jpg","assets/plains-north/images/yellowstone-wy-park/attr2-4.jpg"],"price":"Included with park pass (est.)"},{"description":"America's largest hot spring — a rainbow-colored, football-field-sized pool that's almost too vivid to be real. The boardwalk loop is short and easy, and the overlook from the Fairy Falls trail gives the best view. Go midday when the steam clears.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Grand%20Prismatic%20Spring%20Yellowstone","name":"Grand Prismatic Spring","officialUrl":"https://www.nps.gov/yell/","photos":["assets/plains-north/images/yellowstone-wy-park/attr3-1.jpg","assets/plains-north/images/yellowstone-wy-park/attr3-2.jpg","assets/plains-north/images/yellowstone-wy-park/attr3-3.jpg","assets/plains-north/images/yellowstone-wy-park/attr3-4.jpg"],"price":"Included with park pass (est.)"},{"description":"The Yellowstone River plunges 308 feet over the Lower Falls into a dramatic yellow-walled canyon. Artist Point and the Brink of the Lower Falls trail offer the classic views. The short, steep Uncle Tom's Trail gets you close to the thunder.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Grand%20Canyon%20of%20the%20Yellowstone","name":"Grand Canyon of the Yellowstone","officialUrl":"https://www.nps.gov/yell/","photos":["assets/plains-north/images/yellowstone-wy-park/attr4-1.jpg","assets/plains-north/images/yellowstone-wy-park/attr4-2.jpg","assets/plains-north/images/yellowstone-wy-park/attr4-3.jpg","assets/plains-north/images/yellowstone-wy-park/attr4-4.jpg"],"price":"Included with park pass (est.)"}],"bestSeason":"June–September","budget":1300,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, meals, and gas; lodging not included.","days":4,"destination":"Yellowstone, WY","driveNotes":"Enter via West Yellowstone (west), Gardiner (north), or Jackson (south) — each adds a different flavor. Distances inside the park are huge: Old Faithful to Canyon is 45+ minutes. Book lodging a year ahead for summer; the north entrance stays open year-round. No gas in much of the park — fill up at every station.","familyFriendly":"Best for ages 5+. Boardwalks are stroller-friendly but stay on them — the ground is dangerously hot. Wildlife jams thrill kids; bring binoculars.","heroPhoto":"assets/plains-north/images/yellowstone-wy-park/hero.jpg","highlights":["Watch Old Faithful erupt with the crowds","See the rainbow colors of Grand Prismatic Spring","Stand at Artist Point over the Grand Canyon of the Yellowstone","Spot bison, bears, and wolves in Hayden and Lamar Valleys","Walk the boardwalks of the steaming Norris Geyser Basin"],"id":"yellowstone-wy-park","interests":["family","nature","outdoors","scenic"],"itinerary":[{"afternoon":{"cost":"Included with park pass (est.)","description":"Walk the boardwalks of the Upper Geyser Basin — the densest geyser field on Earth. Beyond Old Faithful, the Morning Glory Pool and Castle Geyser delight. The visitor center predicts the next big eruptions.","stop":"Old Faithful & Upper Geyser Basin","time":"1:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Dinner at the Old Faithful Inn's grand dining room or the casual cafeteria. Then an evening ranger talk — summer programs run nightly and kids love them.","stop":"Old Faithful area evening","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"$35/vehicle, 7-day pass (est.)","description":"Enter through the west entrance and drive to Madison Junction, watching for elk and bison along the Madison River. Stop at the visitor center to plan your days and check eruption predictions.","stop":"West entrance & Madison River","time":"9:00 AM – 12:00 PM"},"title":"Geysers Begin"},{"afternoon":{"cost":"Included with park pass (est.)","description":"The overlook from the Fairy Falls trailhead gives the famous aerial-style view of the spring's rainbow rings. The boardwalk loop at ground level is short and stunning. Midday light is best for photos.","stop":"Grand Prismatic Spring overlook","time":"1:30 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free (est.)","description":"Back to the Old Faithful area for dinner and one more eruption viewing. The geyser at sunset, with fewer crowds, is magical.","stop":"Evening at Old Faithful","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Drive to the Midway Geyser Basin for the boardwalk around Grand Prismatic and the vivid Excelsior Geyser crater. Arrive by 10 AM for parking — this lot fills fast.","stop":"Midway Geyser Basin","time":"10:00 AM – 12:30 PM"},"title":"Prismatic Colors"},{"afternoon":{"cost":"Included with park pass (est.)","description":"Cross Dunraven Pass to Tower Fall and continue into Lamar Valley for the evening wildlife shift. Wolves and bears are most active at dusk. Bring dinner fixings for a picnic at a pullout.","stop":"Tower Fall & Lamar Valley","time":"2:00 PM – 7:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Stay in the valley until dusk for the best wildlife viewing, then drive carefully back — animals on the road are common after dark. An unforgettable day.","stop":"Lamar Valley at dusk","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"Included with park pass (est.)","description":"Drive to Canyon Village and the Grand Canyon of the Yellowstone. Artist Point's view of the 308-foot Lower Falls is the park's most famous vista. Walk part of the South Rim Trail for more overlooks.","stop":"Grand Canyon of the Yellowstone","time":"9:00 AM – 12:30 PM"},"title":"Canyon & Wildlife"},{"afternoon":{"cost":"Gas only (est.)","description":"Exit via the south to Jackson (2 hours) or the west to West Yellowstone (1 hour). Either gateway has an airport and full services.","stop":"Drive home","time":"1:00 PM – 4:00 PM"},"day":4,"evening":{"cost":"Free (est.)","description":"Four days in Yellowstone barely scratches the surface — families leave already planning the return trip. The wildlife memories last a lifetime.","stop":"Farewell","time":"4:00 PM – 5:00 PM"},"morning":{"cost":"Included with park pass (est.)","description":"One last geyser basin: Norris, the park's hottest and most otherworldly, with its milky pools and hissing vents. The boardwalk loops are easy and fascinating — a perfect final morning.","stop":"Norris Geyser Basin","time":"9:00 AM – 11:30 AM"},"title":"Farewell"}],"lat":44.13486,"lng":-110.66627,"overview":"Yellowstone is the original national park and still the most astonishing — half the world's geysers, the Grand Canyon of the Yellowstone, and wildlife that stops traffic. Four days lets a family see the geyser basins, the canyon, and the great wildlife valleys without racing. Book lodging early and prepare for the trip of a lifetime. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Old Faithful Visitor Education Center","Canyon Visitor Education Center","Albright Visitor Center (Mammoth)"],"region":"Northwest WY","related":["gardiner-mt-yellowstone","jackson-wy-teton","glacier-mt-park"],"restaurants":[{"detail":"Grand historic dining room near Old Faithful (reservations essential).","name":"Old Faithful Inn Dining Room","price":"$$"},{"detail":"Casual West Yellowstone favorite for burgers and huckleberry shakes.","name":"Wild West Pizzeria","price":"$"},{"detail":"Hearty mountain fare at the park's south entrance area.","name":"Lake Yellowstone Hotel Dining Room","price":"$$"}],"state":"WY","stateName":"Wyoming","tagline":"The original national park — geysers, canyons, and wildlife beyond imagination.","title":"Yellowstone, WY: Four-Day National Park Adventure","tripType":"national park adventure","imageAsset":"assets/plains-north/images/yellowstone-wy-park/hero.jpg"},{"attractions":[{"description":"America's most dramatic mountain range rising straight from the valley floor — no foothills, just 7,000 feet of granite. Jenny Lake, Mormon Row, and the 42-mile scenic loop offer endless viewpoints. Moose and bears are common along the roads at dawn.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Grand%20Teton%20National%20Park","name":"Grand Teton National Park","officialUrl":"https://www.nps.gov/grte/","photos":["assets/plains-north/images/jackson-wy-teton/attr1-1.jpg","assets/plains-north/images/jackson-wy-teton/attr1-2.jpg","assets/plains-north/images/jackson-wy-teton/attr1-3.jpg","assets/plains-north/images/jackson-wy-teton/attr1-4.jpg"],"price":"$35/vehicle, 7-day pass (est.)"},{"description":"The park's most beloved lake, with a scenic shuttle boat across to the Cascade Canyon trailhead. The easy loop around the south end suits families, and the views of the Cathedral Group are unbeatable. Arrive early — the parking lot fills by 10 AM.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Jenny%20Lake%20Grand%20Teton%20National%20Park","name":"Jenny Lake","officialUrl":"https://www.nps.gov/grte/","photos":["assets/plains-north/images/jackson-wy-teton/attr2-1.jpg","assets/plains-north/images/jackson-wy-teton/attr2-2.jpg","assets/plains-north/images/jackson-wy-teton/attr2-3.jpg","assets/plains-north/images/jackson-wy-teton/attr2-4.jpg"],"price":"Included with park pass; shuttle ~$20/adult (est.)"},{"description":"Jackson's famous town square, with elk-antler arches on all four corners. The boardwalks, shops, and summer shootout reenactments give it an old-west feel. Evening is liveliest, with street performers and the Million Dollar Cowboy Bar nearby.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Jackson%20Town%20Square%20Jackson%20WY","name":"Jackson Town Square","officialUrl":"https://www.jacksonholechamber.com/","photos":["assets/plains-north/images/jackson-wy-teton/attr3-1.jpg","assets/plains-north/images/jackson-wy-teton/attr3-2.jpg","assets/plains-north/images/jackson-wy-teton/attr3-3.jpg","assets/plains-north/images/jackson-wy-teton/attr3-4.jpg"],"price":"Free to explore (est.)"},{"description":"A stunning museum overlooking the National Elk Refuge, with world-class wildlife art and a 3/4-mile sculpture trail. Kids love the outdoor sculptures and the hands-on discovery gallery. The views from the terrace are spectacular.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=National%20Museum%20of%20Wildlife%20Art%20Jackson%20WY","name":"National Museum of Wildlife Art","officialUrl":"https://www.wildlifeart.org/","photos":["assets/plains-north/images/jackson-wy-teton/attr4-1.jpg","assets/plains-north/images/jackson-wy-teton/attr4-2.jpg","assets/plains-north/images/jackson-wy-teton/attr4-3.jpg","assets/plains-north/images/jackson-wy-teton/attr4-4.jpg"],"price":"$18/adult, kids under 18 free (est.)"}],"bestSeason":"June–September","budget":1300,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, shuttle, meals, and gas; lodging not included.","days":4,"destination":"Jackson, WY","driveNotes":"Jackson is at the south end of Grand Teton, 1 hour from Yellowstone's south entrance and 5 hours from Salt Lake City. The park's 42-mile loop is an easy drive; Jenny Lake parking fills by 10 AM — go early or take the shuttle. Jackson lodging is pricey — book far ahead.","familyFriendly":"Best for ages 5+. Jenny Lake's trails and the town square suit all ages; the scenic loop is perfect for car-napping toddlers.","heroPhoto":"assets/plains-north/images/jackson-wy-teton/hero.jpg","highlights":["See the Tetons reflected in Jenny Lake","Pose under the elk-antler arches","Ride the Jenny Lake shuttle boat","Explore world-class wildlife art","Drive the 42-mile Teton Park Road loop"],"id":"jackson-wy-teton","interests":["family","nature","scenic","outdoors","museums"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Pose under the famous elk-antler arches, browse the western shops, and catch the summer shootout reenactment. The boardwalks are stroller-friendly and the ice cream shops are plentiful.","stop":"Jackson Town Square","time":"2:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Dinner downtown — Jackson's restaurants range from chuckwagon to upscale. An evening stroll as the Tetons turn pink caps the day.","stop":"Dinner in Jackson","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Free to explore (est.)","description":"Ease in with the National Elk Refuge overlook (winter sleigh rides are famous, summer brings wildlife viewing) and the town's morning calm. Stock up on picnic supplies for park days.","stop":"National Elk Refuge overlook","time":"9:30 AM – 11:30 AM"},"title":"Town Square Day"},{"afternoon":{"cost":"$18/adult, kids free (est.)","description":"This world-class museum's wildlife art and 3/4-mile sculpture trail captivate all ages. The terrace views over the Elk Refuge are stunning. The hands-on discovery gallery is perfect for kids.","stop":"National Museum of Wildlife Art","time":"1:30 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free (est.)","description":"Back in Jackson for dinner and the lively town square scene. Summer brings free concerts to the town green.","stop":"Jackson evening","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$35/vehicle, 7-day pass (est.)","description":"Drive the 42-mile Teton Park Road loop, stopping at the famous viewpoints: Schwabacher Landing, Mormon Row's barns, and Oxbow Bend. Dawn is best for moose. Allow a full morning with stops.","stop":"Grand Teton scenic loop","time":"8:00 AM – 12:00 PM"},"title":"Teton Loop"},{"afternoon":{"cost":"Free (est.)","description":"Drive to the Laurance Rockefeller Preserve for its easy, beautiful trails, or relax at String Lake's calm swimming beach. The preserve's visitor center is a serene, kid-friendly stop.","stop":"Laurance Rockefeller Preserve or String Lake","time":"1:30 PM – 4:30 PM"},"day":3,"evening":{"cost":"$50–$70 for dinner (est.)","description":"A final Jackson dinner — try the famous elk or bison dishes. The town square at night, lit up, is a lovely farewell.","stop":"Farewell dinner in Jackson","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"$20/adult shuttle (est.)","description":"Arrive at Jenny Lake by 9 AM for parking. Ride the shuttle boat across, then hike the easy trail to Hidden Falls and Inspiration Point. The views up Cascade Canyon are spectacular.","stop":"Jenny Lake","time":"9:00 AM – 1:00 PM"},"title":"Jenny Lake"},{"afternoon":{"cost":"Gas only (est.)","description":"Jackson has an airport inside the national park — the most scenic departure in America. If driving, US-26 east or ID-22 west connect to interstates.","stop":"Drive home","time":"1:00 PM – 3:00 PM"},"day":4,"evening":{"cost":"Free (est.)","description":"Four days among the Tetons leaves families changed — the mountains have that effect. Start planning the return trip.","stop":"Farewell","time":"3:00 PM – 4:00 PM"},"morning":{"cost":"Free (est.)","description":"A slow final morning: breakfast in Jackson, one last look at the Tetons from the Elk Refuge overlook, and souvenir shopping. The mountains will be waiting.","stop":"Farewell Jackson","time":"9:00 AM – 12:00 PM"},"title":"Farewell"}],"lat":43.48024,"lng":-110.76237,"overview":"Jackson pairs America's most dramatic mountain range with a genuinely fun old-west town. The Tetons rise 7,000 feet straight from the valley — no foothills — and Jenny Lake, Mormon Row, and the scenic loop deliver constant wow. Four days lets you savor the park and the town without rushing. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["National Museum of Wildlife Art","Jackson Hole Historical Society & Museum","Craig Thomas Discovery Center (Moose)"],"region":"Jackson Hole","related":["yellowstone-wy-park","gardiner-mt-yellowstone","stanley-id-sawtooths"],"restaurants":[{"detail":"Jackson landmark for elk, bison, and mountain trout.","name":"The Granary","price":"$$"},{"detail":"Fun, casual spot with creative comfort food.","name":"Hand Fire Pizza","price":"$"},{"detail":"Classic western steakhouse on the town square.","name":"The Wort Hotel's Silver Dollar Bar & Grill","price":"$$"}],"state":"WY","stateName":"Wyoming","tagline":"The Tetons' dramatic peaks, a famous town square, and world-class wildlife art.","title":"Jackson, WY: Four-Day Teton Adventure","tripType":"teton adventure","imageAsset":"assets/plains-north/images/jackson-wy-teton/hero.jpg"},{"attractions":[{"description":"Five world-class museums under one roof: the Buffalo Bill, Plains Indian, Cody Firearms, Draper Natural History, and Whitney Western Art museums. The raptor show and Plains Indian powwow (summer) are highlights. Plan a full day — families consistently call it the best museum in the Rockies.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Buffalo%20Bill%20Center%20of%20the%20West%20Cody%20WY","name":"Buffalo Bill Center of the West","officialUrl":"https://centerofthewest.org/","photos":["assets/plains-north/images/cody-wy-west/attr1-1.jpg","assets/plains-north/images/cody-wy-west/attr1-2.jpg","assets/plains-north/images/cody-wy-west/attr1-3.jpg","assets/plains-north/images/cody-wy-west/attr1-4.jpg"],"price":"$25/adult, kids under 18 free (est.)"},{"description":"A recreated 1890s frontier town with 26 authentic buildings, including cabins used by Butch Cassidy's gang. Boardwalks, antique shops, and summer gunfight reenactments make the Old West feel real. Kids love the general store's candy counter.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Old%20Trail%20Town%20Cody%20WY","name":"Old Trail Town","officialUrl":"https://www.oldtrailtown.org/","photos":["assets/plains-north/images/cody-wy-west/attr2-1.jpg","assets/plains-north/images/cody-wy-west/attr2-2.jpg","assets/plains-north/images/cody-wy-west/attr2-3.jpg","assets/plains-north/images/cody-wy-west/attr2-4.jpg"],"price":"$12/adult, kids 6–12 $6 (est.)"},{"description":"The world's longest-running nightly rodeo, every summer night since 1938. Bull riding, barrel racing, and clown acts thrill kids of all ages. Arrive early for good seats — it's an authentic, family-friendly slice of the West.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Cody%20Nite%20Rodeo%20Cody%20WY","name":"Cody Nite Rodeo","officialUrl":"https://www.codystampederodeo.com/","photos":["assets/plains-north/images/cody-wy-west/attr3-1.jpg","assets/plains-north/images/cody-wy-west/attr3-2.jpg","assets/plains-north/images/cody-wy-west/attr3-3.jpg","assets/plains-north/images/cody-wy-west/attr3-4.jpg"],"price":"$25/adult, $13/child (est.)"},{"description":"A 325-foot engineering marvel on the Shoshone River, with a visitor center explaining its 1910 construction. The views from the top stretch down the canyon toward Yellowstone. Free tours run in summer — a quick, impressive stop.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Buffalo%20Bill%20Dam%20Cody%20WY","name":"Buffalo Bill Dam & Visitor Center","officialUrl":"https://www.usbr.gov/","photos":["assets/plains-north/images/cody-wy-west/attr4-1.jpg","assets/plains-north/images/cody-wy-west/attr4-2.jpg","assets/plains-north/images/cody-wy-west/attr4-3.jpg","assets/plains-north/images/cody-wy-west/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"June–September","budget":900,"budgetNote":"Estimate for 2 adults + 2 kids: museum and rodeo tickets, meals, and gas; lodging not included.","days":3,"destination":"Cody, WY","driveNotes":"Cody is 50 miles east of Yellowstone's east entrance on US-14/16/20 — the most scenic park approach. Billings is 2 hours north; the Beartooth Highway (summer only) connects to Red Lodge. Book rodeo tickets ahead for summer weekends; the town fills up.","familyFriendly":"Best for ages 5+. The museums engage all ages; the rodeo runs late (8 PM) so plan a restful afternoon.","heroPhoto":"assets/plains-north/images/cody-wy-west/hero.jpg","highlights":["Explore five museums at the Buffalo Bill Center of the West","Cheer at the nightly Cody Nite Rodeo","Wander the 1890s buildings of Old Trail Town","Stand atop the 325-foot Buffalo Bill Dam","Drive the scenic route to Yellowstone's east entrance"],"id":"cody-wy-west","interests":["family","historical-sites","museums","outdoors"],"itinerary":[{"afternoon":{"cost":"$12/adult, kids 6–12 $6 (est.)","description":"Wander the boardwalks of this recreated 1890s town — 26 authentic buildings including cabins tied to Butch Cassidy. Summer gunfight reenactments and the old-time candy store delight kids.","stop":"Old Trail Town","time":"1:30 PM – 4:00 PM"},"day":1,"evening":{"cost":"$25/adult, $13/child (est.)","description":"The main event: the world's longest-running nightly rodeo. Bull riding, barrel racing, and rodeo clowns under the lights. Arrive by 7:30 for good seats — it's been running every summer night since 1938.","stop":"Cody Nite Rodeo","time":"8:00 PM – 10:00 PM"},"morning":{"cost":"$25/adult, kids free (est.)","description":"Dive into five museums under one roof — Buffalo Bill, Plains Indian, firearms, natural history, and western art. The live raptor show (summer) is a highlight. Plan 3–4 hours minimum.","stop":"Buffalo Bill Center of the West","time":"9:00 AM – 12:30 PM"},"title":"Museums & Rodeo"},{"afternoon":{"cost":"Free (est.)","description":"Drive 10 minutes west to the 325-foot dam on the Shoshone River. The visitor center's free exhibits explain the 1910 engineering feat, and the canyon views toward Yellowstone are spectacular.","stop":"Buffalo Bill Dam","time":"1:30 PM – 3:30 PM"},"day":2,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner downtown — Cody's restaurants lean hearty and western. The historic Irma Hotel's dining room is a fun splurge with its famous cherrywood bar.","stop":"Dinner in Cody","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Included with museum ticket (est.)","description":"Return to the Center of the West for the museums you missed — most families need two visits. The Draper Natural History museum's alpine-to-plains journey is excellent for kids.","stop":"Buffalo Bill Center, continued","time":"9:30 AM – 12:30 PM"},"title":"Dam & Downtown"},{"afternoon":{"cost":"Included with park pass; gas extra (est.)","description":"The 50-mile drive to Yellowstone's east entrance follows the Shoshone River through spectacular canyon country. Even a half-day in the park's Lake area makes a great finale.","stop":"Yellowstone east entrance drive (optional)","time":"12:00 PM – 5:00 PM"},"day":3,"evening":{"cost":"Gas only (est.)","description":"Cody has a regional airport; Billings is 2 hours north on US-212. Depart after lunch for an easy travel day.","stop":"Drive home","time":"3:00 PM – 5:00 PM"},"morning":{"cost":"Free to explore (est.)","description":"A slow morning on Sheridan Avenue — western shops, the historic Irma Hotel, and a hearty breakfast. Pick up cowboy hats for the kids.","stop":"Downtown Cody","time":"9:00 AM – 12:00 PM"},"title":"Farewell"}],"lat":44.52609,"lng":-109.05653,"overview":"Cody is Buffalo Bill's town — the gateway to Yellowstone's east entrance and home to one of America's best western museums. The nightly summer rodeo, a recreated 1890s frontier town, and a towering dam fill three days with authentic Old West adventure. It's touristy in the best way: everything is built for families. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Buffalo Bill Center of the West (full day)","Cody's Historic Irma Hotel (tour + dining)","Heart Mountain Interpretive Center (30 min away)"],"region":"Park County","related":["yellowstone-wy-park","gardiner-mt-yellowstone","devils-tower-wy-monument"],"restaurants":[{"detail":"Historic 1902 hotel dining room with the famous cherrywood bar.","name":"Irma Hotel Restaurant","price":"$$"},{"detail":"Casual Cody favorite for burgers and local brews.","name":"Cody Steakhouse","price":"$$"},{"detail":"Old-fashioned soda fountain with burgers and shakes.","name":"The Soda Fountain","price":"$"}],"state":"WY","stateName":"Wyoming","tagline":"Buffalo Bill's town — five great museums, a nightly rodeo, and Yellowstone's doorstep.","title":"Cody, WY: Three-Day Wild West Adventure","tripType":"wild west adventure","imageAsset":"assets/plains-north/images/cody-wy-west/hero.jpg"},{"attractions":[{"description":"America's first national monument — an 867-foot volcanic rock tower rising straight from the prairie. The 1.3-mile Tower Trail circles the base through boulder fields and pine forest. Climbers dot the face in summer; prairie dogs entertain at the base.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Devils%20Tower%20National%20Monument","name":"Devils Tower National Monument","officialUrl":"https://www.nps.gov/deto/","photos":["assets/plains-north/images/devils-tower-wy-monument/attr1-1.jpg","assets/plains-north/images/devils-tower-wy-monument/attr1-2.jpg","assets/plains-north/images/devils-tower-wy-monument/attr1-3.jpg","assets/plains-north/images/devils-tower-wy-monument/attr1-4.jpg"],"price":"$25/vehicle, 7-day pass (est.)"},{"description":"The easy 1.3-mile paved trail circling the tower's base — the best way to experience its scale. Boulder fields, ponderosa pines, and constant new angles keep kids engaged. Allow 1–2 hours with stops.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tower%20Trail%20Devils%20Tower","name":"Tower Trail","officialUrl":"https://www.nps.gov/deto/","photos":["assets/plains-north/images/devils-tower-wy-monument/attr2-1.jpg","assets/plains-north/images/devils-tower-wy-monument/attr2-2.jpg","assets/plains-north/images/devils-tower-wy-monument/attr2-3.jpg","assets/plains-north/images/devils-tower-wy-monument/attr2-4.jpg"],"price":"Included with park pass (est.)"},{"description":"One of North America's oldest and largest buffalo jumps, where Plains tribes hunted bison for centuries. The visitor center and short trails explain the ingenious hunting method. A fascinating, lesser-known stop 45 minutes south.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Vore%20Buffalo%20Jump%20Sundance%20WY","name":"Vore Buffalo Jump","officialUrl":"https://www.vorebuffalojump.org/","photos":["assets/plains-north/images/devils-tower-wy-monument/attr3-1.jpg","assets/plains-north/images/devils-tower-wy-monument/attr3-2.jpg","assets/plains-north/images/devils-tower-wy-monument/attr3-3.jpg","assets/plains-north/images/devils-tower-wy-monument/attr3-4.jpg"],"price":"$10/adult, kids under 12 free (est.)"},{"description":"The Belle Fourche River winds through the monument, with cottonwood groves and the quiet South Side picnic area. The river trail is an easy family walk with tower views. Great for a picnic lunch away from the crowds.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Belle%20Fourche%20River%20Devils%20Tower","name":"Belle Fourche River Picnic Area","officialUrl":"https://www.nps.gov/deto/","photos":["assets/plains-north/images/devils-tower-wy-monument/attr4-1.jpg","assets/plains-north/images/devils-tower-wy-monument/attr4-2.jpg","assets/plains-north/images/devils-tower-wy-monument/attr4-3.jpg","assets/plains-north/images/devils-tower-wy-monument/attr4-4.jpg"],"price":"Included with park pass (est.)"}],"bestSeason":"May–October","budget":600,"budgetNote":"Estimate for 2 adults + 2 kids: park pass, meals, and gas; lodging not included.","days":2,"destination":"Devils Tower, WY","driveNotes":"Devils Tower is in northeastern Wyoming, 30 minutes from Sundance and about an hour from the Black Hills. WY-24 is the scenic approach — the tower appears suddenly and dramatically. Climbing closures occur in June out of respect for tribal ceremonies; check before promising the kids a climber sighting.","familyFriendly":"Best for ages 4+. The Tower Trail is paved and gentle; the prairie dog town is toddler catnip.","heroPhoto":"assets/plains-north/images/devils-tower-wy-monument/hero.jpg","highlights":["Circle the 867-foot tower on the Tower Trail","Watch climbers scale the rock face","Meet the prairie dogs at the monument entrance","Picnic by the Belle Fourche River","Explore the ancient Vore Buffalo Jump"],"id":"devils-tower-wy-monument","interests":["family","nature","scenic","outdoors","historical-sites"],"itinerary":[{"afternoon":{"cost":"Included with park pass (est.)","description":"Walk the 1.3-mile Tower Trail around the base — boulder fields, pines, and ever-changing views of the tower. Watch climbers on the face and prairie dogs at the trailhead. The visitor center's exhibits add context.","stop":"Tower Trail & visitor center","time":"1:30 PM – 4:30 PM"},"day":1,"evening":{"cost":"$40–$60 for dinner (est.)","description":"Dinner in Sundance or Hulett — small-town Wyoming at its friendliest. The tower at sunset, glowing orange, is worth the drive back for photos.","stop":"Dinner & sunset views","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$25/vehicle (est.)","description":"Arrive via WY-24 for the dramatic first view. Start at the visitor center, then drive the loop to the main viewpoints. The prairie dog town near the entrance entertains kids for ages.","stop":"Devils Tower arrival & viewpoints","time":"9:30 AM – 12:30 PM"},"title":"The Tower"},{"afternoon":{"cost":"$10/adult, kids free (est.)","description":"Drive 45 minutes south to one of North America's oldest buffalo jumps. The sinkhole site and visitor center explain how Plains tribes hunted bison for centuries — a fascinating hidden gem.","stop":"Vore Buffalo Jump","time":"1:00 PM – 3:00 PM"},"day":2,"evening":{"cost":"Gas only (est.)","description":"Devils Tower is an hour from the Black Hills and 30 minutes from I-90 at Sundance. An afternoon departure connects easily to either.","stop":"Drive home","time":"3:30 PM – 5:30 PM"},"morning":{"cost":"Included with park pass (est.)","description":"A quiet morning picnic by the Belle Fourche River in the monument's South Side area. The cottonwoods, the river, and the tower overhead make a peaceful farewell.","stop":"Belle Fourche River picnic","time":"10:00 AM – 12:30 PM"},"title":"River & Farewell"}],"lat":44.58902,"lng":-104.69981,"overview":"Devils Tower is America's first national monument — an 867-foot rock tower that looks like it landed from another planet. The easy Tower Trail circles its base, climbers dot its face, and prairie dogs rule the entrance. It's a perfect two-day stop that pairs beautifully with the Black Hills or Bighorns. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Devils Tower Visitor Center (film + exhibits)","Vore Buffalo Jump Visitor Center","Crook County Museum (Sundance)"],"region":"Northeast WY","related":["black-hills-sd-mountains","deadwood-sd-wildwest","cody-wy-west"],"restaurants":[{"detail":"Classic small-town Wyoming cafe near the monument.","name":"The Ponderosa Cafe","price":"$"},{"detail":"Sundance favorite for hearty American fare.","name":"Longhorn Saloon & Grill","price":"$$"},{"detail":"Family-friendly spot in Hulett with burgers and shakes.","name":"The Hitching Post","price":"$"}],"state":"WY","stateName":"Wyoming","tagline":"America's first national monument — a rock tower from another planet.","title":"Devils Tower, WY: Two-Day Monument Escape","tripType":"monument escape","imageAsset":"assets/plains-north/images/devils-tower-wy-monument/hero.jpg"},{"attractions":[{"description":"Home of the world's largest outdoor rodeo and western celebration, held every late July since 1896. The Old West Museum on the Frontier Park grounds covers the event's history year-round, with wagons, carriages, and rodeo artifacts. Even off-season, the museum is excellent.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Cheyenne%20Frontier%20Days%20Old%20West%20Museum%20Cheyenne%20WY","name":"Cheyenne Frontier Days Old West Museum","officialUrl":"https://www.cfdrodeo.com/","photos":["assets/plains-north/images/cheyenne-wy-frontier/attr1-1.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr1-2.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr1-3.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr1-4.jpg"],"price":"$12/adult, kids under 12 free (est.)"},{"description":"Wyoming's state history museum, free and surprisingly engaging, with exhibits on the state's Native peoples, pioneers, and wildlife. The hands-on children's areas and the state's story from dinosaurs to today make it a solid family stop.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wyoming%20State%20Museum%20Cheyenne%20WY","name":"Wyoming State Museum","officialUrl":"https://wyoparks.wyo.gov/","photos":["assets/plains-north/images/cheyenne-wy-frontier/attr2-1.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr2-2.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr2-3.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr2-4.jpg"],"price":"Free (est.)"},{"description":"A working bison ranch 20 minutes south of Cheyenne, with train tours through the bison herd, horseback rides, and a family restaurant. Kids love feeding the animals and the western atmosphere. The train ride is the highlight.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Terry%20Bison%20Ranch%20Cheyenne%20WY","name":"Terry Bison Ranch","officialUrl":"https://www.terrybisonranch.com/","photos":["assets/plains-north/images/cheyenne-wy-frontier/attr3-1.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr3-2.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr3-3.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr3-4.jpg"],"price":"$15–$30/person activities (est.)"},{"description":"A beautiful oasis in Lions Park with indoor and outdoor gardens, a children's garden, and a tropical conservatory. The kids' garden with its interactive water features is a delight. Free and peaceful — a lovely contrast to the rodeo energy.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Cheyenne%20Botanic%20Gardens%20Cheyenne%20WY","name":"Cheyenne Botanic Gardens","officialUrl":"https://www.botanic.org/","photos":["assets/plains-north/images/cheyenne-wy-frontier/attr4-1.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr4-2.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr4-3.jpg","assets/plains-north/images/cheyenne-wy-frontier/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"June–September","budget":600,"budgetNote":"Estimate for 2 adults + 2 kids: museum tickets, ranch activities, meals, and gas; lodging not included.","days":2,"destination":"Cheyenne, WY","driveNotes":"Cheyenne is on I-25/I-80 in southeastern Wyoming, 90 minutes north of Denver and 45 from Fort Collins. It's the easiest Wyoming destination to reach. Terry Bison Ranch is 20 minutes south on I-25. If visiting during Frontier Days (late July), book everything months ahead.","familyFriendly":"Best for ages 4+. The bison ranch train and botanic gardens' children's area are toddler-friendly.","heroPhoto":"assets/plains-north/images/cheyenne-wy-frontier/hero.jpg","highlights":["Ride the train through a bison herd at Terry Bison Ranch","Explore rodeo history at the Old West Museum","Discover Wyoming's story at the free State Museum","Play in the children's garden at the Botanic Gardens","Time it for Cheyenne Frontier Days in late July"],"id":"cheyenne-wy-frontier","interests":["family","historical-sites","museums","nature"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Wyoming's state museum covers dinosaurs to the present with hands-on areas for kids. The exhibits on Native peoples and pioneer life are well done. A cool, calm afternoon downtown.","stop":"Wyoming State Museum","time":"1:30 PM – 3:30 PM"},"day":1,"evening":{"cost":"$50–$70 for dinner (est.)","description":"Dinner downtown — Cheyenne's historic district has family-friendly steakhouses and cafes. The historic Plains Hotel and Union Pacific depot area are worth a stroll.","stop":"Downtown Cheyenne dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$12/adult, kids free (est.)","description":"Start at the museum on the Frontier Park grounds — home of the world's largest outdoor rodeo. Wagons, carriages, and rodeo history fill the galleries. In late July, the actual Frontier Days event takes over the town.","stop":"Cheyenne Frontier Days Old West Museum","time":"9:30 AM – 12:00 PM"},"title":"Frontier History"},{"afternoon":{"cost":"Free (est.)","description":"Wander the indoor tropical conservatory and the outdoor children's garden with its interactive water features. A peaceful, beautiful finale before the drive home.","stop":"Cheyenne Botanic Gardens","time":"1:30 PM – 3:30 PM"},"day":2,"evening":{"cost":"Gas only (est.)","description":"Cheyenne is 90 minutes from Denver on I-25. An afternoon departure gets you home for dinner.","stop":"Drive home","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"$15–$30/person (est.)","description":"Drive 20 minutes south to this working bison ranch. The train tour through the herd is the highlight — kids can feed bison from the train. Horseback rides and the restaurant round out the visit.","stop":"Terry Bison Ranch","time":"9:30 AM – 12:30 PM"},"title":"Bison & Gardens"}],"lat":41.13481,"lng":-104.82154,"overview":"Cheyenne is Wyoming's friendly capital — home of the world's largest outdoor rodeo, a free state museum, and a working bison ranch 20 minutes away. It's the easiest Wyoming trip to pull off, 90 minutes from Denver, and pairs frontier history with genuine western fun. Time it for Frontier Days in late July for the full experience. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Wyoming State Museum","Cheyenne Frontier Days Old West Museum","Cheyenne Botanic Gardens conservatory"],"region":"Southeast WY","related":["devils-tower-wy-monument","cody-wy-west","black-hills-sd-mountains"],"restaurants":[{"detail":"Cheyenne landmark for steaks in a historic setting.","name":"The Albany","price":"$$"},{"detail":"Fun, family-friendly spot with great burgers.","name":"2 Doors Down","price":"$$"},{"detail":"Classic diner breakfasts downtown.","name":"Luxury Diner","price":"$"}],"state":"WY","stateName":"Wyoming","tagline":"Wyoming's frontier capital — the world's biggest rodeo, bison herds, and western history.","title":"Cheyenne, WY: Two-Day Frontier City Stop","tripType":"frontier city stop","imageAsset":"assets/plains-north/images/cheyenne-wy-frontier/hero.jpg"}];
